impl<'value, 'loc: 'value, 'eval> EvalContext<'value, 'loc> for BlockScope<'value, 'loc, 'eval> {
    fn record_deprecation(&mut self, notice: String) {
        self.parent.record_deprecation(notice)
    }

    fn record_warning(
        &mut self,
        site: &FileLocation<'_>,
        argument: &str,
        map: &str,
        notice: String,
    ) {
        self.parent.record_warning(site, argument, map, notice)
    }

    fn record_capture_warning(&mut self, site: &FileLocation<'_>, capture: &str, notice: String) {
        self.parent.record_capture_warning(site, capture, notice)
    }

    fn record_unraised_refusal(
        &mut self,
        site: &FileLocation<'_>,
        context: &str,
        verdict: crate::rules::UnraisedVerdict,
        refusals: &[String],
    ) {
        crate::rules::eval::count_unraised_refusal_forward();
        self.parent
            .record_unraised_refusal(site, context, verdict, refusals)
    }

    fn data_file_name(&self) -> Option<&'value str> {
        self.parent.data_file_name()
    }

    fn case_label(&self) -> Option<&str> {
        self.parent.case_label()
    }

    /// Forgets this block's own captures and merged keys, and deliberately not the parent's, for the
    /// trait's reason. Nothing calls this on a block today, since it is called between top-level rules
    /// and a block does not outlive one; it is answered so that the scope decides rather than inherits.
    fn reset_captures(&mut self) {
        self.captured.clear();
        self.merged.clear();
        self.capture_frames.clear();
        // Every name that was ever captured or merged here reads differently now (an empty selection
        // again), so each is another generation; a name never held reads as it did, 0.
        for generation in self.capture_generations.values_mut() {
            *generation += 1;
        }
    }

    /// Forwarded: a block holds key captures of its own and no index captures, so the write goes on
    /// to the scope that keeps them; the trait's former no-op default swallowed it at this link.
    fn add_variable_capture_index(&mut self, name: &str, index: Rc<PathAwareValue>) -> Result<()> {
        self.parent.add_variable_capture_index(name, index)
    }

    fn record_deprecation_once(
        &mut self,
        kind: DeprecationKind,
        site: &FileLocation<'_>,
        notice: String,
    ) -> bool {
        self.parent.record_deprecation_once(kind, site, notice)
    }

    fn predicate_regexes(&self, site: &FileLocation<'_>) -> Rc<CompiledRegexes> {
        self.parent.predicate_regexes(site)
    }

    /// When the reading ends (`mode` is `Off`), takes back what it wrote into this block's memo and
    /// captures, then forwards, so every scope between the one the measurement started in and the root
    /// does the same for its own stores; a switch between two measuring modes is a nested reading and
    /// takes nothing back, as the root scope's `set_measurement` says. See `ReadingUndo`.
    fn set_measurement(&mut self, mode: Measurement) {
        if mode == Measurement::Off {
            let names_cut_back = self.reading_undo.roll_back(
                &mut self.scope.resolved_variables,
                &mut self.scope.variable_shapes,
                &mut self.scope.function_entries,
                &mut self.scope.failed_assignments,
                &mut self.captured,
                &mut self.capture_frames,
            );
            // Only a name whose `captured` entry the roll-back cut back is another generation, and only
            // that name: whatever its capture read as while that reading was on, the keys are the real
            // run's again now. The count is deliberately conservative: the appends made under the reading
            // already counted the name up once each (`add_variable_capture`), nothing undoes a count, and
            // the roll-back counts it up once more, so a name that came back with its keys unchanged is
            // re-keyed and a `when` settled for its old id is measured again. That is a measurement spent,
            // never a measurement missed: a reading that appended to a name is rare (a `let` the reading
            // resolved whose query captures), and restoring the count from the undo log would rest on no
            // id being built while a measurement is on, which holds today and nothing enforces. A reading
            // that appended nothing, which is every measurement of a `when` whose conditions capture
            // nothing (the common gate over a `let` and a capture the body bound before the block), leaves
            // the captures and their bindings as they were; counting a generation up there re-keyed the
            // bindings after every measurement, so the next resource of a type block never matched the
            // record and the gate was measured once per bucket again.
            for name in names_cut_back {
                self.bump_capture_generation(name);
            }
        }
        self.parent.set_measurement(mode)
    }

    fn measurement(&self) -> Measurement {
        self.parent.measurement()
    }

    fn when_is_settled(
        &self,
        site: &FileLocation<'loc>,
        direction: MoveDirection,
        bindings: Option<&BTreeSet<BindingId<'value>>>,
    ) -> bool {
        self.parent.when_is_settled(site, direction, bindings)
    }

    fn when_has_settled_measurements(
        &self,
        site: &FileLocation<'loc>,
        direction: MoveDirection,
    ) -> bool {
        self.parent.when_has_settled_measurements(site, direction)
    }

    fn settle_when(
        &mut self,
        site: &FileLocation<'loc>,
        direction: MoveDirection,
        bindings: Option<BTreeSet<BindingId<'value>>>,
    ) {
        self.parent.settle_when(site, direction, bindings)
    }

    /// This block's own `let`s first, which is the order `lookup` reads them in; a name the walk reaches
    /// that this block does not bind at all is the parent's to answer, with the hops taken here added.
    /// A name this block binds by a literal or a capture is on no chain, whatever an outer `let` of the
    /// same name is.
    fn function_chain(&mut self, variable_name: &str) -> Option<FunctionChain<'value>> {
        let bound_otherwise = |name: &str| {
            self.scope.literals.contains_key(name)
                || self.captured.contains_key(name)
                || self.merged.contains_key(name)
        };
        match walk_function_chain(&self.scope, &bound_otherwise, variable_name) {
            ChainWalk::Call(chain) => Some(chain),
            ChainWalk::Left {
                name,
                exact_alias,
                hops,
            } => {
                let parent = self.parent.function_chain(name)?;
                Some(FunctionChain {
                    root: parent.root,
                    exact_alias: exact_alias && parent.exact_alias,
                    hops: hops + parent.hops,
                })
            }
            ChainWalk::NotAChain => None,
        }
    }

    /// A root bound in this block is read off this block's memo; a chain that leaves the block is the
    /// parent's to answer, from the name it left at, so the entries are always the binding scope's own
    /// and never those of a same-named binding in the scope that asked.
    fn function_result_entries(
        &mut self,
        variable_name: &str,
    ) -> Option<Result<Rc<FunctionEntries>>> {
        let bound_otherwise = |name: &str| {
            self.scope.literals.contains_key(name)
                || self.captured.contains_key(name)
                || self.merged.contains_key(name)
        };
        match walk_function_chain(&self.scope, &bound_otherwise, variable_name) {
            ChainWalk::Call(chain) => {
                let root = chain.root;
                if let Some(entries) = held_entries_of_root(&mut self.scope, root) {
                    return Some(Ok(entries));
                }
                // Held by nothing: read under a nested quiet reading and keep nothing; see
                // `held_entries_of_root` and `NestedMeasurement`. The set matches by content, since no
                // clone points at this reading's objects.
                count_function_entry_root_lookup();
                let mut quiet = NestedMeasurement::enter(self, Measurement::Quiet);
                let values = quiet.lookup(root, MergedKeys::Visible, UnboundName::Error);
                Some(values.map(|values| Rc::new(FunctionEntries::of_fresh(&values))))
            }
            ChainWalk::Left { name, .. } => self.parent.function_result_entries(name),
            ChainWalk::NotAChain => None,
        }
    }

    fn has_deprecation_site(&mut self, kind: DeprecationKind, site: &FileLocation<'_>) -> bool {
        self.parent.has_deprecation_site(kind, site)
    }

    fn has_quiet_filter_site(
        &mut self,
        kind: DeprecationKind,
        site: &FileLocation<'_>,
        map_path: &str,
    ) -> bool {
        self.parent.has_quiet_filter_site(kind, site, map_path)
    }

    fn has_quiet_record_at(&mut self, kind: DeprecationKind, site: &FileLocation<'_>) -> bool {
        self.parent.has_quiet_record_at(kind, site)
    }

    fn record_quiet_filter_site(
        &mut self,
        kind: DeprecationKind,
        site: &FileLocation<'_>,
        map_path: &str,
    ) {
        self.parent.record_quiet_filter_site(kind, site, map_path)
    }

    /// This block's captures first, then its own `let`s, then the parent's, the order `lookup` reaches
    /// them in. A name a filter in this block captured, or a nested block handed up, is the capture's
    /// whatever an outer `let` of the same name is: `Tags[ t | ... ]` then `%t[*][ ... ]` must not
    /// be announced as a filter through a file-level `let t`, which never held those maps.
    fn variable_binding_source(
        &mut self,
        variable_name: &str,
    ) -> Option<BindingSource<'value, 'loc>> {
        if self.captured.contains_key(variable_name) || self.merged.contains_key(variable_name) {
            return None;
        }
        match self.scope.binding_source(variable_name) {
            Some(source) => Some(source),
            None => self.parent.variable_binding_source(variable_name),
        }
    }

    /// This block's captures first, then its own `let`s, then the parent's, the order
    /// `variable_binding_source` reads them in. A `let` this block owns decides, and the walk goes on
    /// from here, so `let m = %p` in a called rule's body follows `p` from the body, where it is the
    /// rule's parameter; a name this block does not bind is the parent's to answer, and the parent then
    /// follows its own binding's head from itself, so a body `let s = Resources...` beside `%doc[ ... ]`
    /// never stands in for the file-level `s` that `let doc = json_parse(%s)` names. A function's result
    /// a `let` of this block holds is keyed by that `let`'s name when the block runs once per evaluation
    /// (a rule body: the same condition `binding_owners` takes its document-level branch on), since the
    /// result is then one map for the run, as a file-level `let`'s is; a `let` of a block bound again on
    /// every resource or call holds a result built again each time and records nothing
    /// (`quiet_record_key_of_function_result`); passing `None` for every block would probe the `%doc`
    /// map of `rule r { let doc = json_parse(Resources.P.Properties.Policy)  AWS::S3::Bucket { %doc[ Tags
    /// !exists ] empty } }` once per bucket where once per evaluation does. The key is read under the
    /// SITE (the filter's location), so two rule bodies that each `let doc = ...` are two records
    /// whatever their names.
    fn quiet_record_key_step(&mut self, variable_name: &str, hops_left: usize) -> QuietRecordKey {
        if self.captured.contains_key(variable_name) || self.merged.contains_key(variable_name) {
            return QuietRecordKey::PathByFallback;
        }
        let once_per_evaluation =
            self.start == QueryStart::Document && !self.parent.within_parameterized_call();
        match self.scope.binding_source(variable_name) {
            Some(source) => quiet_record_key_of_binding(
                self,
                source,
                once_per_evaluation.then_some(variable_name),
                hops_left,
            ),
            None => self.parent.quiet_record_key_step(variable_name, hops_left),
        }
    }

    /// Forwarded: a block body's root is the root of the scope the block opened from.
    fn root_quiet_record_key(&mut self, hops_left: usize) -> QuietRecordKey {
        self.parent.root_quiet_record_key(hops_left)
    }

    /// The same split as `function_chain`: a name this block binds by a literal, a
    /// capture or a merged key is held as bound; one it binds by a call or a query is held when its own
    /// `lookup` has memoized it, and not before, whatever an outer `let` of the same name holds; a name
    /// it does not bind is the parent's to answer for.
    fn variable_is_resolved(&self, variable_name: &str) -> bool {
        if self.scope.literals.contains_key(variable_name)
            || self.captured.contains_key(variable_name)
            || self.merged.contains_key(variable_name)
            || self.scope.resolved_variables.contains_key(variable_name)
        {
            return true;
        }
        if self.scope.function_expressions.contains_key(variable_name)
            || self.scope.variable_queries.contains_key(variable_name)
        {
            return false;
        }
        self.parent.variable_is_resolved(variable_name)
    }

    /// This block's literals, then the enclosing scopes'; a name this block binds to a query, a function
    /// call or a capture of its own shadows the enclosing scopes and holds nothing here (a capture is
    /// the query-bound name it is declared by, as the root's reading says), and so does a name merged up
    /// from a finished inner block (`merged`): the comparison read the merged keys, so the outer binding
    /// is not what it compared against, and the merged keys depend on the order the iterations ran in.
    /// The capture and the merged key are read BEFORE this block's own literals, as `lookup` reads them:
    /// a block's `let w = 'Env'` whose inner block merged `w` = `Team` up compared against `Team`. A
    /// block `let` whose query is a bare `%v` is followed to its root, as `binding_step` follows it: within
    /// this block's own `let`s first, then to the enclosing scopes for a root the block does not bind, so
    /// `let f = %forbidden` over a file-level `let forbidden = 'Secret'` is the literal here; a name met
    /// twice on the chain ends it.
    fn literal_binding(&self, variable_name: &str) -> Option<Vec<Rc<PathAwareValue>>> {
        let mut name = variable_name;
        let mut followed: Vec<&str> = Vec::new();
        loop {
            if self.captured.contains_key(name) || self.merged.contains_key(name) {
                return None;
            }
            if let Some(literal) = self.scope.literals.get(name) {
                return Some(vec![Rc::clone(literal)]);
            }
            if self.scope.function_expressions.contains_key(name) {
                return None;
            }
            let Some(query) = self.scope.variable_queries.get(name).copied() else {
                return self.parent.literal_binding(name);
            };
            let root = bare_variable_root(&query.query)?;
            if followed.contains(&root) {
                return None;
            }
            followed.push(root);
            name = root;
        }
    }

    fn query(&mut self, query: &'value [QueryPart<'loc>]) -> Result<Vec<QueryResult>> {
        let start = self.start;
        let in_predicate = self.in_predicate;
        let results = query_retrieval(0, query, self.root(), self, start, in_predicate)?;
        // The bound-map probe, when it is above this block, judges grounding from what the body looked
        // up; see `EvalContext::note_query_grounding`.
        self.parent.note_query_grounding(query, &results);
        Ok(results)
    }

    /// Passed up, for the same reason this block's own queries are: a `when` block nested inside this
    /// block's body runs its queries in a scope of its own and tells this block, and the probe above
    /// judges from the whole body. The trait's default swallowed it here, so
    /// `%r[ when Properties !exists { when Type !exists { MyBucket exists } } ]` read as anchored by
    /// nothing where the same lookup one level shallower anchored it.
    fn note_query_grounding(&mut self, query: &'value [QueryPart<'loc>], results: &[QueryResult]) {
        self.parent.note_query_grounding(query, results);
    }

    fn find_parameterized_rule(
        &mut self,
        rule_name: &str,
    ) -> Result<&'value ParameterizedRule<'loc>> {
        self.parent.find_parameterized_rule(rule_name)
    }

    fn root(&mut self) -> Rc<PathAwareValue> {
        Rc::clone(&self.scope.root)
    }

    fn document_root(&mut self) -> Rc<PathAwareValue> {
        self.parent.document_root()
    }

    fn query_start(&self) -> QueryStart {
        self.start
    }

    fn empty_selection(&self) -> Option<Rc<EmptySelection>> {
        // A block nested in a body that runs over an empty selection reads the same selection: the
        // scope that opened the body holds the note, so the question goes up.
        self.parent.empty_selection()
    }

    fn in_predicate(&self) -> bool {
        self.in_predicate
    }

    /// Forwarded: a block's body reads beside a map as the scope that opened the block does.
    fn reads_beside_the_map(&self) -> bool {
        self.parent.reads_beside_the_map()
    }

    /// This scope's root, the value the block is over: the scope beside a map a key filter in the body
    /// is applied to.
    fn fallback_root(&mut self) -> Rc<PathAwareValue> {
        self.root()
    }

    fn is_top_level_alias(&self, variable_name: &str, merged: MergedKeys) -> bool {
        // A binding in this block answers for itself, and it is the population only if this block's
        // queries start at the document: `let r = Resources` inside a type block names a resource's
        // own `Resources` key, if it has one. The binding is read through `binding_step`, which follows
        // a chain of `let` aliases within this block to the query at its end and reads the stores in
        // `lookup`'s order under the reading the asking clause has, so a capture this block made, a key
        // a nested block handed up (under `Visible`), a literal or a function result is `Unqueried` and
        // not an alias of anything. A name the chain leaves this block for (`let r = %all` here, `all`
        // bound outside) is the parent's, asked about that name under the onward reading the step hands
        // back, the same reading `variable_binding_query` passes on: dropping it asked the parent
        // `Visible` for a nested block, and the two walks over one chain disagreed. The `Document` test
        // is this block's own: a chain that leaves the block is judged where it ends, so `let r = %all`
        // inside a type block names the document's `all`, not a resource-level key.
        match self.binding_step(variable_name, merged) {
            BindingStep::Query(query) => {
                binds_a_single_key(Some(query)) && self.start == QueryStart::Document
            }
            BindingStep::Unqueried => false,
            BindingStep::Deferred(name, onward) => self.parent.is_top_level_alias(name, onward),
        }
    }

    fn binding_owners(&self, variable_name: &str) -> Option<BTreeSet<BindingId<'value>>> {
        // A `let`, a capture or a merged key bound in this block is read afresh each time the block
        // runs. When the block itself runs at the document and outside any parameterized rule's call,
        // it runs once per evaluation, so a `let` there is its own owner: a rule body's `let` is. A
        // capture or a merged key there is its own owner too, at the block's capture GENERATION: its
        // value changes while the block runs, a declared name reading as an empty selection before its
        // filter has run and as the captured keys after, so `rule r { check(1) Resources[ x | Type ==
        // 'A' ] !empty check(1) }` hands the called rule's `when` two different `%x`s from one block, and
        // a measurement of the first call must decide nothing for the second. The declared name and the
        // captured keys are kept under one name string, so naming either by its address alone made them
        // one binding, and answering `None` for both kept the `when` open for every evaluation, so
        // `rule r { let f = ...  Resources[ x | Type == 'A' ] !empty  AWS::S3::Bucket when %x IN %f
        // { ... } }`, whose `%x` cannot change once the filter has run, was measured once per bucket
        // (a clone of the result and the conditions read again, each time) where it had settled after
        // one. The generation, counted up for a NAME on every key captured or merged into this block
        // under it, gives the empty selection and the captured keys two ids and a stretch of reads with
        // no new capture of that name one, so the first shape is measured twice and the second once; a
        // type block handing its own captures (`t`) up on every resource leaves `x`'s id alone, where
        // one count for the whole block re-keyed `x` per resource and measured the second shape once per
        // bucket again. Any
        // other block is bound again for every resource or call: a type block's body, a `when` block
        // inside one, a parameterized rule's body, whose block starts where the caller's queries do but
        // is bound again for every call from that call's arguments. There a `let` is the same value
        // every time only when its right-hand side rests on document-level bindings and literals alone,
        // and then it rests on what they rest on AND on itself: the `let`'s own identity is part of the
        // answer, because what the right-hand side rests on does not tell one `let` from another.
        // `let q = %p` over a root `%p` rests on `%p`'s binding and on `q`; over a caller's body `let`
        // it rests on that caller's binding, so another caller's call is another key. Without its own
        // identity, two different `let`s of one name whose right-hand sides read the same root bindings
        // got one key: `rule r1 { AWS::S3::Bucket { let y = to_lower(%props.First) p(1) } }` beside
        // `rule r2 { AWS::S3::Bucket { let y = to_lower(%props.Second) p(1) } }`, both resting on
        // `{props}`, so the first caller's finished measurement of `p`'s `when` settled it for the
        // second caller, whose `y` moved, and the line was lost, where the release before kept every
        // caller-bound name open. The same `let` keeps one address for every resource and every call,
        // so a `let` read once per bucket still settles once. In such a block a capture or a merged
        // key is the resource's or the call's, and `None`. A name this block does not bind is the
        // parent's.
        if !self.binds_here(variable_name) {
            return self.parent.binding_owners(variable_name);
        }
        if self.start == QueryStart::Document && !self.parent.within_parameterized_call() {
            // A `let` by its own node; a capture or a declared capture name by its name string at that
            // NAME's capture generation in this block; a merged key is nobody's binding, `None`. A
            // `let` bound to a query or a call rests besides on every `%name` its right-hand side
            // reaches (`owners_resting_on`), so a rule body's `let bs = %b` over the body's own
            // `Resources[ b | ... ]` rests on the capture at its generation and is re-keyed when the
            // filter binds `b`, where its own id alone kept the quiet probes' memo serving the empty
            // selection a probe read before the filter ran; a `let` reaching a merged key is nobody's.
            // Walked on every ask, never through the root's memo (`memoized_binding_owners`): a block
            // binding's owners rest on other names' capture generations (`let bs = %b.Properties.Name`
            // moves from `{b@0, bs}` to `{b@1, bs}` when the body's filter binds `b`), which the
            // binding's own id does not carry, so an answer kept by that id would hand the probes after
            // the filter the set from before it and serve them its value.
            let site = self.document_level_site(variable_name)?;
            let mut owners = if self.captured.contains_key(variable_name) {
                BTreeSet::new()
            } else {
                match self.scope.binding_source(variable_name) {
                    Some(source) => owners_resting_on(variable_name, &source, self)?,
                    None => BTreeSet::new(),
                }
            };
            owners.insert(site);
            return Some(owners);
        }
        // A key this block's own filter captured, or a nested block handed up, is the resource's or
        // the call's, `None`, before the `let` store is asked: a `let` of the same name that the capture
        // or the merged key shadows must not answer for it.
        if self.captured.contains_key(variable_name) || self.merged.contains_key(variable_name) {
            return None;
        }
        // Walked on every ask too: a called rule's body `let q = %y` rests on the CALLER's `y`, so two
        // callers are two owner sets under one `let` site, and an answer kept by the site would settle
        // the second caller's `when` on the first caller's binding.
        let mut rests_on = match self.scope.binding_source(variable_name) {
            Some(BindingSource::Literal(_)) => BTreeSet::new(),
            Some(BindingSource::Let(query)) => query_document_level_bindings(&query.query, self)?,
            Some(BindingSource::FunctionCall(call)) => {
                function_call_document_level_bindings(call, self)?
            }
            _ => return None,
        };
        rests_on.insert(self.scope.binding_site(variable_name)?);
        Some(rests_on)
    }

    /// Forwarded: the table is the root's.
    fn value_before_the_wildcard_clones(&self) -> Option<Rc<RefCell<ValueBeforeClones>>> {
        self.parent.value_before_the_wildcard_clones()
    }

    /// Forwarded: the memo is the root's.
    fn document_binding_memo(&self) -> Option<Rc<RefCell<DocumentBindingMemo<'value>>>> {
        self.parent.document_binding_memo()
    }

    fn binding_owners_memo(&self) -> Option<Rc<RefCell<BindingOwnersMemo<'value>>>> {
        self.parent.binding_owners_memo()
    }

    fn note_binding_walk_limit(&self, text: String) {
        self.parent.note_binding_walk_limit(text)
    }

    /// This block's own `let`s count as the root's assignments do: while one is being resolved
    /// (`resolving_let`), a probe that runs inside its right-hand side (the kept-scalar check of a filter
    /// the `let` holds, reading a `%name` quietly) keeps nothing in the root's memo
    /// (`QuietScope::document_memo_key`), since what it reads mid-resolution can be partial: a capture
    /// arriving while the `let` resolves belongs to it (`bind_assignment_captures` skips the assignment
    /// being resolved at the root, and this block's `let` is the same shape one scope down). Reading the
    /// root alone here let such a probe file a value for the evaluation.
    fn resolving_a_binding(&self) -> bool {
        self.resolving_let > 0 || self.parent.resolving_a_binding()
    }

    fn within_parameterized_call(&self) -> bool {
        self.parent.within_parameterized_call()
    }

    fn rule_status(
        &mut self,
        rule_name: &'value str,
        role: super::eval::ClauseRole,
    ) -> Result<Status> {
        self.parent.rule_status(rule_name, role)
    }

    fn resolve_variable(&mut self, variable_name: &'value str) -> Result<Vec<QueryResult>> {
        let values = self.lookup(variable_name, MergedKeys::Visible, UnboundName::Error)?;
        Ok(self.measured_if_bound_here(variable_name, values))
    }

    /// This block's own bindings first and then the parent's, which is the order `lookup` reaches them
    /// in. A block-level `let` shadowing a file-level one of the same name is the case that needs the
    /// order: the shadowing binding is the one that produced the values.
    ///
    /// The shadowing binding need not be a query, which is what reading `variable_queries` alone
    /// missed. A block-level `let n = [ "a", "b" ]` binds `n` in `literals`, so `lookup` answers with
    /// the list -- while this deferred past the block and reported an enclosing `let n = <projecting
    /// query>`. The clause then read the whole literal list as one value: `some %n[*] == "a"` over
    /// `let n = Cfg.Items.*` at file level failed with "PathAwareValues are not comparable array,
    /// String", and deleting the unrelated file-level assignment made it pass.
    ///
    /// `capture_names` is *not* consulted, unlike `RootScope`'s `capture_sources`. It is not a binding:
    /// `lookup` reads it only to decide what an unbound name means after the deferral has failed, and
    /// an outer `let` of that name is a real binding this block's own capture says nothing about -- see
    /// `lookup`'s unbound arm for the false failure that reading it earlier produced.
    ///
    /// The deferral goes on as [`MergedKeys::Hidden`] whatever this question was, exactly as `lookup`
    /// defers to `resolve_variable_from_nested_block` whatever the lookup was: a name this block does
    /// not bind is being read from outside the block, so the union a finished block left in an enclosing
    /// scope is not the binding that produced the values this clause will see. Passing `merged` on
    /// unchanged is the mistake to avoid -- it would let a clause at the parent's own level and a clause
    /// nested one block deeper be judged against the same binding, which is the distinction the two
    /// maps exist to keep.
    ///
    /// A bare `%v` binding is followed from here, as `RootScope::variable_binding_query` follows one from
    /// there, and for the same reason that one does: `%v` in a `let` this block wrote means what it means
    /// in this block, and the reader that will interpret the answer can be a scope further in that binds
    /// the name differently. The two move together because a block-level chain and a file-level one are one
    /// chain written at two depths -- `rule main { let b = %a  when Cfg exists { let a = "lit"
    /// %b[ Meta.V == 1 ].Meta.V == 9 } }` over `let a = Cfg.Items.*` is the block spelling, and it
    /// reported SKIP at exit 0 the same way. Repairing only the root scope would have left it, and the
    /// only difference from the spelling that reports is a nested `let a` the clause never mentions.
    ///
    /// That reason carries over. `RootScope`'s termination argument does not, and must not be read as
    /// covering this walk: there the walk cannot leave one scope's own `variable_queries`, while this one
    /// does leave, at the `None` arm's `self.parent.variable_binding_query(name, MergedKeys::Hidden)`. The
    /// bound here rests on a different property, and it is a data-dependency one rather than a locality
    /// one. A scope can only name bindings at or outside itself, and this forwarding is strictly outward,
    /// so the graph the walk traverses is a DAG by construction. Nothing in that turns on where any of this
    /// code sits, which is what makes it falsifiable only by changing what feeds what.
    ///
    /// Measured, and the two halves are separate claims. A ring among one scope's own `let`s never reaches
    /// evaluation: `first_let_cycle` refuses each at parse, exit 5, naming the ring -- at chain lengths 2,
    /// 3 and 5, at file, block and nested-block level, with bare, dotted and starred links, and through a
    /// parameter argument. And a ring spanning two scopes is not constructible *as a ring*, because the
    /// outer scope cannot name the inner binding: file-level `let a = %b` with a block-level `let b = %a`
    /// reaches evaluation and exits 5 on `Could not resolve variable by name b across scopes`, as do a
    /// three-scope attempt and a block reading a file-level link. No shape exits 134 and none hangs.
    ///
    /// So `followed.contains(&root)` is unreachable from any `.guard` file, here and in `RootScope`'s copy.
    /// Removed from both walks, no test in the lib suite reddens and every ring shape above still
    /// exits 5. What is claimed there is that nothing discriminates the guard, not that the suite has some
    /// size: a total drifts with the denominator and went stale here within the hour, from one test being
    /// added two commits later, while "no test reddens" did not.
    /// That zero is deadness rather than missing coverage, and no `.guard` file can be written to
    /// close it: reaching this branch at all means hand-building a scope whose `variable_queries` the parser
    /// would have rejected.
    ///
    /// Keep it regardless, which is what the length of this paragraph is for. It is a bound whose two
    /// enabling properties are both external to it -- rings refused at parse, and forwarding strictly
    /// outward. If either stops holding it becomes load-bearing, and the change that stops it would be
    /// somewhere else entirely. Deleting this as dead code, and reading it as the thing that prevents a live
    /// crash, are both available from this code alone, so both are named here.
    ///
    /// A followed step that leaves this block defers as the asked name does, and the parent then follows
    /// from itself: `%a` written in a `let` here, for an `a` this block does not bind, is a read that
    /// crosses out of the block, so it is `Hidden` there for the reason the asked name is.
    ///
    /// The bound-without-a-query gate is the same code as `RootScope`'s and does not behave the same way,
    /// because what a scope does when the gate *fails* to fire is what decides whether firing mattered.
    /// That one falls through to `None` for a name it does not hold, which makes every arm of its gate
    /// unobservable; this one falls through to the parent, which can answer with an outer `let`'s
    /// projecting query. So the gate is live here, on followed names as much as on the asked one: a
    /// block-level `let n = [ "p", "q" ]` over a file-level `let n = Cfg.Items.*`, read as `%b[*]` through
    /// `let b = %n`, is answered "did not enumerate" only because the gate stops the walk at this block's
    /// literal. Skipping it for followed names reaches the file-level projection instead and reports it for
    /// values that binding never produced, turning a PASS into exit 19.
    /// `a_followed_step_is_judged_by_the_stores_of_the_scope_that_holds_it` in `eval_tests.rs` is that
    /// cell, and the literal there is a list rather than a string on purpose -- enumerating a scalar is a
    /// pass-through, so the same shape over `let n = "p"` measures nothing.
    ///
    /// The `Visible` reading on a followed step is unfalsifiable here for the reason recorded in full over
    /// there: it can only be reached through the merged map, and a merged key is a capture, whose slot
    /// decision `binding_is_a_capture` makes rather than this question.
    fn variable_binding_query(
        &mut self,
        variable_name: &str,
        merged: MergedKeys,
    ) -> Option<&'value AccessQuery<'loc>> {
        match self.binding_step(variable_name, merged) {
            BindingStep::Query(query) => Some(query),
            BindingStep::Unqueried => None,
            BindingStep::Deferred(name, onward) => self.parent.variable_binding_query(name, onward),
        }
    }

    fn projection_member_keys(
        &mut self,
        variable_name: &str,
        merged: MergedKeys,
    ) -> Result<Option<Rc<ProjectionKeys>>> {
        match self.binding_step(variable_name, merged) {
            BindingStep::Query(query) => self.keys_of(query),
            BindingStep::Unqueried => Ok(None),
            BindingStep::Deferred(name, onward) => self.parent.projection_member_keys(name, onward),
        }
    }

    /// Where this block's binding for `variable_name` enumerated, as its retrieval reported, read in the
    /// block's own lookup order and never by resolving: a block-level literal, capture or (when
    /// `Visible`) merged key names its value and wins over a shadowed outer `let`, a block-level `let`
    /// bound to a query or a call answers from the shape `lookup` recorded beside its values, and a name
    /// this block does not bind is the parent's to answer under the `Hidden` reading the lookup deferred
    /// with -- so a file-level `let allowed = Types[*]` read from a block that merged a key named
    /// `allowed` takes its values and its shape from the same source.
    ///
    /// The record beside the shape (the maps the last part's `[*]` passed on unchanged in the resolution
    /// of this block's `let`, or the parent's under the same `Hidden` deferral) comes from the same entry
    /// in the same answer; a literal, a capture or a merged key passed nothing on.
    fn variable_shape(
        &mut self,
        variable_name: &str,
        merged: MergedKeys,
    ) -> (RhsEnumeration, PassedOn) {
        if self.scope.literals.contains_key(variable_name)
            || self.holds_own_capture(variable_name, merged)
        {
            return (RhsEnumeration::Names, PassedOn::default());
        }
        if self.scope.function_expressions.contains_key(variable_name)
            || self.scope.variable_queries.contains_key(variable_name)
        {
            return self
                .scope
                .variable_shapes
                .get(variable_name)
                .cloned()
                .unwrap_or_else(|| (RhsEnumeration::Names, PassedOn::default()));
        }
        self.parent
            .variable_shape(variable_name, MergedKeys::Hidden)
    }

    /// This block's own captures and (when `Visible`) merged keys, reached through this block's `let`
    /// aliases of a bare variable (`let names = %buckets`) the way `variable_binding_query` follows them;
    /// else the parent's answer under the `Hidden` reading, the deferral `variable_shape` makes. A name
    /// this block binds to a literal, a call, or a query that is not a bare variable names its value.
    fn variable_lists_keys(&self, variable_name: &str, merged: MergedKeys) -> bool {
        let mut name = variable_name;
        let mut reading = merged;
        let mut followed: Vec<&str> = Vec::new();
        loop {
            if self.holds_own_capture(name, reading) {
                return true;
            }
            if self.scope.literals.contains_key(name)
                || self.scope.function_expressions.contains_key(name)
            {
                return false;
            }
            let Some(query) = self.scope.variable_queries.get(name) else {
                return self.parent.variable_lists_keys(name, MergedKeys::Hidden);
            };
            match bare_variable_root(&query.query) {
                Some(root) if !followed.contains(&root) => {
                    followed.push(root);
                    name = root;
                    reading = MergedKeys::Visible;
                }
                _ => return false,
            }
        }
    }

    fn entry_candidates(
        &mut self,
        values: Vec<Rc<PathAwareValue>>,
        shape: RhsEnumeration,
    ) -> Rc<super::eval::EntryCandidates> {
        self.parent.entry_candidates(values, shape)
    }

    fn query_with_shape(
        &mut self,
        query: &'value [QueryPart<'loc>],
    ) -> Result<(Vec<QueryResult>, RhsEnumeration, PassedOn)> {
        let start = self.start;
        let in_predicate = self.in_predicate;
        let (results, shape, passed_on) =
            query_retrieval_shaped(query, self.root(), self, start, in_predicate)?;
        self.parent.note_query_grounding(query, &results);
        Ok((results, shape, passed_on))
    }

    fn resolve_variable_from_nested_block(
        &mut self,
        variable_name: &'value str,
        unbound: UnboundName,
    ) -> Result<Vec<QueryResult>> {
        let values = self.lookup(variable_name, MergedKeys::Hidden, unbound)?;
        Ok(self.measured_if_bound_here(variable_name, values))
    }

    /// This block's own stores in `lookup`'s order, through this block's own `let` aliases of a bare
    /// variable as `binding_step` follows them, then the parent's at the reading `binding_step` hands
    /// off with, for the same reason it defers: `let x = %t` bound in a type block whose own clause
    /// captured `t` is read as `%t` is. `RootScope`'s copy carries the argument for following aliases.
    fn binding_is_a_capture(&mut self, variable_name: &str, merged: MergedKeys) -> bool {
        let mut name = variable_name;
        let mut reading = merged;
        let mut followed: Vec<&str> = Vec::new();
        loop {
            if self.holds_own_capture(name, reading) {
                return true;
            }
            if self.scope.literals.contains_key(name)
                || self.scope.function_expressions.contains_key(name)
            {
                return false;
            }
            let Some(query) = self.scope.variable_queries.get(name).copied() else {
                let onward = match self.deferral {
                    Deferral::AsNestedBlock => MergedKeys::Hidden,
                    Deferral::AsReader => reading,
                };
                return self.parent.binding_is_a_capture(name, onward);
            };
            match bare_variable_root(&query.query) {
                Some(root) if !followed.contains(&root) => {
                    followed.push(root);
                    name = root;
                    reading = MergedKeys::Visible;
                }
                _ => return false,
            }
        }
    }

    /// Captured here rather than delegated to the parent, because this is the scope the capture
    /// belongs to.
    ///
    /// `RootScope`'s implementation appends and never resets, so a scope that handed captures up to
    /// it would let every key captured by a filter outlive the iteration that produced it and pile up
    /// in one list for the whole file -- and `resolve_variable` reads `resolved_variables` before
    /// `variable_queries`, so the grown list is what a later `%name` would see.
    ///
    /// That is a false PASS, not merely untidy. Over two buckets, one with an enabled config named
    /// `alpha` and one with only `beta`:
    ///
    /// ```text
    /// Resources.*[ Type == 'AWS::S3::Bucket' ] {
    ///     Properties.Config[ cfg | Enabled == true ] !empty
    ///     some %cfg == "alpha"
    /// }
    /// ```
    ///
    /// the second bucket saw `["alpha", "beta"]` and satisfied `some %cfg == "alpha"` on the strength
    /// of the first bucket's key. Adding a *compliant* resource made a non-compliant one pass, and
    /// the non-compliant bucket alone failed correctly -- which is the shape that makes this
    /// dangerous, because the rule looks like it works when tested on one resource at a time.
    ///
    /// A fresh `BlockScope` is built per iteration (`eval_guard_block_clause` loops the block's values
    /// and `eval_general_block_clause` builds a new scope for each), so storing the capture here gives
    /// it exactly the lifetime of the iteration that made it. `resolve_variable` already looks in this
    /// scope before asking the parent, so nothing else has to change.
    ///
    /// `ValueScope` still delegates, and must: it carries no scope of its own, so a capture made under
    /// one lands in the nearest enclosing block, which is the iteration boundary that matters.
    fn add_variable_capture(
        &mut self,
        variable_name: &'value str,
        result: QueryResult,
    ) -> Result<()> {
        // Under a measurement a block that existed before it writes only the captures of a `let` the
        // reading is resolving, and logs them; a capture from a clause evaluated directly is skipped,
        // since the real evaluation already captured the key. See `writes_without_undo`.
        let without_undo =
            writes_without_undo(self.parent.measurement(), self.built_under_measurement);
        if !without_undo && self.resolving_let == 0 {
            return Ok(());
        }
        // A `let` of this block forced on the way by an entry of a loop in the body (the frame was
        // opened while fewer `let`s were being resolved) keeps its keys below that entry's segment:
        // they are the `let`'s, memoised for the block, and every later entry reads them. Parked with the
        // forcing entry, `rule r { let bs = Resources[ b | Type == 'X' ]  Resources.*[ %bs !empty
        // Properties.Target IN %b ] !empty }` read `%b` EMPTY under every resource but the first, and
        // the `IN` over nothing kept each of them as not applicable. Under a measurement's log as well:
        // the log keeps each touched name whole as it stood before the reading (`reading_undo`), so the
        // measured reading files the keys where the real run files them and the roll-back still puts the
        // real run's keys back.
        if !without_undo {
            self.note_capture_touched(variable_name);
        }
        if self
            .capture_frames
            .innermost_let_depth()
            .is_some_and(|depth| depth < self.resolving_let)
            && self.capture_frames.insert_below_segment(
                &mut self.captured,
                variable_name,
                result.clone(),
            )
        {
            self.bump_capture_generation(variable_name);
            return Ok(());
        }
        self.captured.entry(variable_name).or_default().push(result);
        self.bump_capture_generation(variable_name);
        Ok(())
    }

    /// The live length plus the slices the open frames hold parked: the scale the marks are taken on
    /// (`RootScope::variable_capture_len`).
    fn variable_capture_len(&self, variable_name: &str) -> usize {
        self.captured.get(variable_name).map_or(0, Vec::len)
            + self
                .capture_frames
                .parked_len(CaptureHome::Captured, variable_name)
    }

    fn truncate_variable_capture(&mut self, variable_name: &'value str, len: usize) -> Result<()> {
        // As `add_variable_capture`: no cut where that method writes nothing. Under a measurement the
        // cut is one more touch of the name, undone at the reading's end with the rest by putting the
        // list back as it stood before the reading (`reading_undo`). The name's generation moves when
        // its entry does.
        let without_undo =
            writes_without_undo(self.parent.measurement(), self.built_under_measurement);
        if !without_undo && self.resolving_let == 0 {
            return Ok(());
        }
        if !without_undo {
            self.note_capture_touched(variable_name);
        }
        // `len` is on the absolute scale `variable_capture_len` answers on; the frames cut the parked
        // slices first (`CaptureFrames::cut`, as `RootScope::truncate_variable_capture`).
        if self.capture_frames.cut(
            CaptureHome::Captured,
            &mut self.captured,
            variable_name,
            len,
        ) {
            self.bump_capture_generation(variable_name);
        }
        Ok(())
    }

    /// This block keeps its own captures (`add_variable_capture` files here and does not reach up), so
    /// the frames are this block's and nothing is forwarded: a loop in the body scopes the body's
    /// captures, and a file-level assignment a predicate resolves on the way keeps its own keys whole
    /// in the root's store, as a memoised result should (the root's frames file a forced assignment's
    /// keys below the segment the same way this block files a forced `let`'s). The frame records how
    /// many of this block's `let`s are being resolved; `merged` goes with every call.
    fn open_capture_frame(&mut self) {
        // Whether `add_variable_capture` writes right now: with no undo log, or while one of this block's
        // own `let`s is being resolved (the one case a logging reading writes).
        let writes_captures =
            writes_without_undo(self.parent.measurement(), self.built_under_measurement)
                || self.resolving_let > 0;
        self.capture_frames.open(
            CaptureHome::Captured,
            self.resolving_let,
            &self.captured,
            &self.merged,
            writes_captures,
        );
    }

    fn begin_capture_entry(&mut self) {
        self.capture_frames
            .begin_segment(&self.captured, &self.merged);
    }

    /// A parked slice changes what the name reads, so the name's generation moves with it.
    fn end_capture_entry(&mut self) {
        for name in self
            .capture_frames
            .end_segment(&mut self.captured, &mut self.merged)
        {
            self.bump_capture_generation(name);
        }
    }

    fn end_capture_entry_detached(&mut self) -> EntryCaptures<'value> {
        let (changed, captures) = self
            .capture_frames
            .end_segment_detaching(&mut self.captured, &mut self.merged);
        for name in changed {
            self.bump_capture_generation(name);
        }
        captures
    }

    /// A slice filed back changes what the name reads, as its parking did.
    fn refile_captures(&mut self, captures: EntryCaptures<'value>) {
        for name in CaptureFrames::refile(&mut self.captured, &mut self.merged, captures) {
            self.bump_capture_generation(name);
        }
    }

    fn close_capture_frame(&mut self) {
        // A close under a logging reading files an inner frame's forced keys below the frame beneath it
        // (`CaptureFrames::close`, `opened_lens`), moving that frame's segment starts: recorded for the
        // roll-back first, as the writes are.
        if !writes_without_undo(self.parent.measurement(), self.built_under_measurement) {
            self.reading_undo
                .note_frame_starts(&self.capture_frames, true);
        }
        for name in self
            .capture_frames
            .close(&mut self.captured, &mut self.merged)
        {
            self.bump_capture_generation(name);
        }
    }

    /// Filed below the running segment, whether the block writes without an undo log or logs the
    /// reading's writes (while one of its own `let`s is being resolved, the one case a logging reading
    /// writes): the key goes where the real run files it, below the segment, and the name is recorded
    /// whole for the reading's end (`note_capture_touched`), as the root scope files an assignment's
    /// key under a measurement. A logging reading that appended the key instead parked it with the
    /// member whose filter bound it, so a rule-body `let x = Tags[ t | Key == 'Env' ].Sub[ Name IN
    /// %t[*].Value ]` first resolved inside a measured reading read only the current member's `t`.
    /// Where the block writes nothing (a logging reading outside any of its `let`s) nothing is filed, as
    /// `add_variable_capture` files nothing there.
    fn add_variable_capture_key_below_the_entry(
        &mut self,
        variable_name: &'value str,
        key: Rc<PathAwareValue>,
    ) -> Result<()> {
        let result = QueryResult::Resolved(key);
        let without_undo =
            writes_without_undo(self.parent.measurement(), self.built_under_measurement);
        if !without_undo && self.resolving_let == 0 {
            return Ok(());
        }
        if !without_undo {
            self.note_capture_touched(variable_name);
        }
        if !self.capture_frames.insert_below_segment(
            &mut self.captured,
            variable_name,
            result.clone(),
        ) {
            self.captured.entry(variable_name).or_default().push(result);
        }
        self.bump_capture_generation(variable_name);
        Ok(())
    }

    fn add_merged_capture(
        &mut self,
        variable_name: &'value str,
        result: QueryResult,
    ) -> Result<()> {
        if !writes_without_undo(self.parent.measurement(), self.built_under_measurement) {
            return Ok(());
        }
        self.merged.entry(variable_name).or_default().push(result);
        self.bump_capture_generation(variable_name);
        Ok(())
    }
}

impl<'value, 'loc: 'value, 'eval> BlockScope<'value, 'loc, 'eval> {
    /// Under a measurement that logs this block's writes, record how `variable_name` stands before this
    /// reading's first write to or cut of it, so the reading's end puts it back whole (`ReadingUndo`).
    /// The list is cloned once per name, at the first touch (`ReadingUndo::is_logged`), and the frame's
    /// segment starts once per frame (`ReadingUndo::note_frame_starts`); a later touch of a logged name
    /// under a recorded frame clones nothing.
    fn note_capture_touched(&mut self, variable_name: &'value str) {
        self.reading_undo
            .note_frame_starts(&self.capture_frames, false);
        if self.reading_undo.is_logged(variable_name) {
            return;
        }
        let before = self.captured.get(variable_name).cloned();
        self.reading_undo.note_touched(variable_name, before);
    }

    /// One more generation for `variable_name` alone: its `captured` or `merged` entry changed. Other
    /// names' bindings stay as they were, which is what lets a `when` over `%x` stay settled while a type
    /// block hands `t` up on every resource.
    fn bump_capture_generation(&mut self, variable_name: &'value str) {
        *self.capture_generations.entry(variable_name).or_insert(0) += 1;
    }

    /// The generation `variable_name` is at in this block: 0 for a name never captured, merged or reset
    /// here.
    fn capture_generation_of(&self, variable_name: &str) -> u32 {
        self.capture_generations
            .get(variable_name)
            .copied()
            .unwrap_or(0)
    }

    /// The binding a name this block holds is, for `binding_owners` when the block runs at the document
    /// level, read from the stores in `lookup`'s order so the id names the store the value is read from:
    /// a key a filter captured during this iteration, by the name as the store spells it (the capture
    /// stores share the filter's one name string) at that NAME's capture generation in this block
    /// (`capture_generation_of`; another name's captures leave it); then a key a nested block handed up
    /// (`merged`), which is nobody's binding, `None` whatever other store holds the name too; then a
    /// literal `let`, by its node; then a query or function `let`, or a value resolved for the name, by
    /// the let's node (`Scope::binding_site`); then a name a filter in this block declares, the empty
    /// selection before its filter has run, at the capture generation. `None` for a name no store holds.
    ///
    /// The order matters twice. A merged key is read two ways under one name, `Visible` by a
    /// parameterized rule's own `when` called from this block's own level and `Hidden` by the same `when`
    /// called from a `when` block nested in it, which reads past the merged keys to this block's declared
    /// name, an empty selection (`lookup`'s deferral): two values under one id let the nested call's
    /// finished measurement settle the body-level call whose `when` had moved, and its notice was lost;
    /// nobody's binding keeps both calls measured, as every capture was before the generation existed.
    /// And a merged key shadows a query or function `let` of this block: the parser refuses a block that
    /// both assigns and declares one name ("Variable x is both assigned and declared"), so a block's own
    /// `let` and its own capture never meet, but a `when` block nested in the body may capture the name
    /// the body's `let` binds and hand it up (the shadowing notice names the shape), and `lookup` then
    /// reads the merged key before the `let`. Reading the `let` stores first named that value by the
    /// let's fixed id, so a `when` settled while `%x` read the `let` stayed settled after the merged key
    /// changed `%x`: the stale settlement the generation exists to prevent, and a notice lost.
    fn document_level_site(&self, variable_name: &str) -> Option<BindingId<'value>> {
        // The capture and the merged key before the `let`, the order `lookup` reads them in: a block
        // whose nested block handed `w` up is read as the merged key, nobody's binding, whatever `let w`
        // this block declares; a `let` read first would make a shadowed literal its own owner, a constant
        // for the record and the memo while the name read changes per iteration.
        if let Some((name, _)) = self.captured.get_key_value(variable_name) {
            return Some(BindingId::of_capture(
                name,
                self.capture_generation_of(name),
            ));
        }
        if self.merged.contains_key(variable_name) {
            return None;
        }
        if let Some((name, _)) = self.scope.literals.get_key_value(variable_name) {
            return Some(BindingId::of_name(name));
        }
        self.scope.binding_site(variable_name).or_else(|| {
            self.capture_names
                .get(variable_name)
                .copied()
                .map(|name| BindingId::of_capture(name, self.capture_generation_of(name)))
        })
    }
}

impl<'value, 'loc: 'value, 'eval> RecordTracer<'value> for BlockScope<'value, 'loc, 'eval> {
    fn start_record(&mut self, context: &str) -> Result<()> {
        self.parent.start_record(context)
    }

    fn end_record(&mut self, context: &str, record: RecordType<'value>) -> Result<()> {
        self.parent.end_record(context, record)
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, Default)]
pub(crate) struct Messages {
    pub(crate) custom_message: Option<String>,
    pub(crate) error_message: Option<String>,
    #[serde(skip_serializing)]
    pub(crate) location: Option<Location>,
    /// Whether the evaluator's message here embeds a refusal, copied from the record it was built from
    /// (`BlockCheck::refusal`, `ValueCheck::refusal`, `NamedStatus::refusal`,
    /// `ComparisonClauseCheck::refusal`, `InComparisonCheck::refusal`); the comparison records' sentences
    /// name the value the query traversed to beside the record's message and keep the record's kind, so
    /// a refusal decided beside an absent value, or beside a value no listed entry accepted under `IN`,
    /// prints whole with the value, whose parts a refusal bounds (`template_part`). The console reporter
    /// bounds a refusal's line by `LONGEST_REFUSAL_MESSAGE` and every other message by
    /// `LONGEST_RECORDED_MESSAGE`, and reads the kind here rather than from the text, which cannot say
    /// (a message that wraps another error displays the same wrapper a refusal does). Not part of the
    /// serialized report: `-o json` and the other structured outputs keep their shape, and a report
    /// read back carries `false`.
    #[serde(skip)]
    pub(crate) refusal: bool,
}

/// The explanation for a rule that did not apply, if the evaluator recorded one.
///
/// A skipped rule reaches the reporters as a name and nothing else, so an explanation written onto a
/// skip record would be constructed and discarded without this walk. Walking the rule's own subtree is
/// what makes the message reachable, so a message may be added to any of the block-shaped records
/// below and it will surface.
///
/// The first explanation found wins rather than all of them being concatenated. A rule that skips
/// usually skips for one reason, and a reporter line that grows without bound with nesting depth is
/// worse than a slightly incomplete one.
///
/// Children are searched before the record's own message, because the deeper message is the more
/// specific one. Taking `own` first made the specific messages unreachable in the case that
/// motivated them: a type block always attaches a summary to its own SKIP ("every X was exempted by
/// the `when` condition"), so the recursion never ran and the undecidable-comparison explanation
/// underneath it -- the one naming `Size: "50"` as a string that cannot be compared against an
/// integer -- was built, recorded, and never read. Pinned by
/// `a_specific_skip_reason_is_not_shadowed_by_the_block_summary`.
/// The walk stops at a referenced rule rather than reading its records as this rule's own. A rule that
/// references another gets that other rule's whole subtree nested inside its own, so a search that
/// recurses freely reads a gate belonging to the referenced rule and reports it as the referring rule's.
/// `rule g { inner }` has no `when`, no filter and makes no comparison, and it said "one of its
/// conditions was not met; a comparison it made reported ..." on the strength of `inner`'s `when`. See
/// [`Walked::crosses_into_another_rule`].
pub(crate) fn find_skip_reason(record: &EventRecord<'_>) -> Option<String> {
    skip_reason_reached_through(record, Walked::nothing_yet())
}

/// What the walk down to an explanation has passed through.
///
/// Two questions, both about the path rather than the record holding the explanation, because a
/// comparison does not know what encloses it: which kind of gate decided this, and whose rule the gate
/// belongs to. Each is the difference between a sentence a reader can act on and one that sends them
/// looking for something they never wrote.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
struct Walked {
    gate: ReachedThrough,
    /// Whether the walk is already inside a rule. Only true below a [`RecordType::RuleCheck`], which is
    /// what makes a second one recognizable as somebody else's rule rather than this one's.
    in_rule: bool,
}

/// Which kind of gate a skip explanation was reached through, accumulated on the way down.
///
/// The explanation itself is recorded on a comparison, and a comparison does not know what encloses
/// it. What encloses it is the whole difference between two sentences a reader acts on differently, so
/// it is carried here rather than guessed at the leaf. See the `ClauseValueCheck` arm of
/// [`own_skip_reason`] for the sentences and for the measured list of paths that arrive.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ReachedThrough {
    /// Nothing on the path so far says. Deliberately the starting value and deliberately not treated
    /// as "condition": a record shape nobody has enumerated yet gets a sentence that claims neither.
    Neither,
    /// A `when` condition -- on the rule, on a block, or on a type block.
    Condition,
    /// A query filter, with no `when` condition anywhere above it.
    Filter,
}

impl Walked {
    fn nothing_yet() -> Self {
        Self {
            gate: ReachedThrough::Neither,
            in_rule: false,
        }
    }

    /// Folds one record on the path into what has been passed through.
    fn descend(self, record: &EventRecord<'_>) -> Self {
        Self {
            gate: self.gate.descend(record),
            in_rule: self.in_rule || is_rule(record),
        }
    }

    /// True when `child` starts a different rule's records than the one being explained.
    ///
    /// The boundary is observed rather than added: a referenced rule is evaluated into a nested
    /// [`RecordType::RuleCheck`], carrying its own name, exactly where its records begin. Nothing had to
    /// be invented to see it, which matters -- deriving "whose gate is this" from anything softer than
    /// the marker the tree already sets is how the referring rule came to claim the referenced rule's
    /// condition in the first place.
    ///
    /// Conditional on `in_rule`, and that is not a detail. The entry point is sometimes a rule's own
    /// record -- `common.rs` calls this per skipped rule -- and sometimes the file's, whose children are
    /// all `RuleCheck`. Refusing every `RuleCheck` would make the file-level call answer nothing at all;
    /// refusing only a second one draws the line where a rule stops describing itself.
    fn crosses_into_another_rule(self, child: &EventRecord<'_>) -> bool {
        self.in_rule && is_rule(child)
    }
}

fn is_rule(record: &EventRecord<'_>) -> bool {
    matches!(record.container, Some(RecordType::RuleCheck(_)))
}

impl ReachedThrough {
    /// Folds one record on the path into the answer.
    ///
    /// `Condition` is sticky, and that is the substantive choice here rather than a shortcut. A filter
    /// can sit inside a `when` -- `when Resources.*[ Size > 10 ] not empty` -- and there the rule does
    /// have a condition and the condition genuinely was not met, so the condition sentence is the true
    /// one even though the refusal came from a filter within it.
    fn descend(self, record: &EventRecord<'_>) -> Self {
        match &record.container {
            Some(
                RecordType::RuleCondition(_)
                | RecordType::WhenCondition(_)
                | RecordType::TypeCondition(_),
            ) => Self::Condition,
            // Keyed on the three `*Condition` variants above rather than on `WhenCheck`, because
            // `WhenCheck` is the block a condition guards rather than the condition: its own
            // `WhenCondition` child is what holds the comparisons, and that is the record a refusal is
            // actually filed under.
            Some(RecordType::Filter(_)) if self != Self::Condition => Self::Filter,
            _ => self,
        }
    }
}

fn skip_reason_reached_through(record: &EventRecord<'_>, walked: Walked) -> Option<String> {
    let walked = walked.descend(record);
    record
        .children
        .iter()
        .filter(|child| !walked.crosses_into_another_rule(child))
        .find_map(|child| skip_reason_reached_through(child, walked))
        .or_else(|| own_skip_reason(record, walked.gate))
}

/// The explanation this record carries itself, ignoring its children.
///
/// Split out of [`find_skip_reason`] so the recursion order is one readable expression, and so the
/// block-shaped variants share a single body -- they did not, and `clippy::collapsible_match` failed
/// the `cargo clippy -- -D warnings` gate on the duplicate.
fn own_skip_reason(record: &EventRecord<'_>, reached: ReachedThrough) -> Option<String> {
    match &record.container {
        Some(RecordType::TypeCheck(TypeBlockCheck { block, .. }))
        | Some(RecordType::GuardClauseBlockCheck(block))
        | Some(RecordType::WhenCheck(block))
        | Some(RecordType::BlockGuardCheck(block))
        | Some(RecordType::Disjunction(block)) => match block {
            BlockCheck {
                status: Status::SKIP,
                message,
                ..
            } => message.clone(),
            _ => None,
        },

        // A clause that failed *and* explained itself, reached while walking a rule that skipped.
        //
        // The wording claims only what a SKIP proves. A sentence saying the condition "could not be
        // decided" is false in both cases that reach here.
        //
        // A refusal to compare KINDS is a decided answer under the semantics `Unanswerable` draws:
        // `NOT IN` reads such a pair as "not a member", which rule authors rely on when they write a
        // value against both spellings it might carry. So a condition that failed on one was decided,
        // and calling it undecidable contradicts the distinction the evaluator is built on.
        //
        // A comparison the engine ABANDONED cannot have produced this SKIP either, because
        // `undecided_gate` raises on one instead of letting it answer -- so reaching a SKIP with such an
        // explanation recorded proves some OTHER value decided the clause. Measured on
        // `when Vals[*].V NOT IN [/(?!x)((a+)+)b/, 7]` over `V: 7` and a thirty-character `a` string:
        // the rule skips because `7` is named by the denylist, and that sentence would blame the regex
        // pair -- the one pair the evaluator explicitly refused to let decide anything.
        //
        // So both facts are stated and neither is attributed: what the gate was, and what one of its
        // comparisons reported. A reader who needs to know whether the explanation caused the outcome
        // has the clause and the operands in front of them.
        //
        // # Which shapes arrive here, measured rather than argued
        //
        // Opening every explanation with "one of its conditions was not met" would be a claim about
        // the rule's shape rather than about the comparison. A query filter refuses comparisons with
        // no `when` existing anywhere: `rule g { Resources.*[ Properties.Size > 10 ] {
        // Properties.X == 1 } }` over `Size: "50"` exits 0 SKIP in a rule with zero `when` tokens, and
        // that sentence would send the reader to inspect something they never wrote.
        //
        // The reason that survived is the shape of this comment, not the shape of the sentence. It
        // enumerated two arriving populations, argued a third impossible and declared a fourth
        // unreachable, so the arm read as fully accounted for and nobody re-measured it. It was not
        // accounted for. Walking the record tree, seven paths reach this arm:
        //
        //   RuleCondition                                  a `when` on the rule
        //   WhenCheck > WhenCondition                       a `when` on a block
        //   TypeCheck > TypeBlock > TypeCondition           a `when` on a type block
        //   RuleCondition > Disjunction                     a `when` holding an `or`
        //   RuleCondition > .. > Filter                     a filter INSIDE a `when`
        //   BlockGuardCheck > Filter                        a query filter, no `when` anywhere
        //   GuardClauseBlockCheck > Filter                  a filter bound by a `let`, no `when`
        //
        // Three pass through a filter and two of those three carry no condition record at all. Those
        // two are the false ones; the fifth is not, because a rule whose `when` selects nothing does
        // have a condition and it was not met.
        //
        // So the sentence is chosen from the path, which [`ReachedThrough`] carries down. A condition
        // anywhere above earns the condition sentence. A filter with nothing above it gets a sentence
        // about a filter. A path with neither gets both claims dropped and keeps only the explanation --
        // no measured shape lands there today, and that is the point of it: the next record shape added
        // to this tree gets a sentence that is merely incomplete instead of one that is wrong.
        //
        // Telling FAIL and SKIP apart needs a status meaning "could not tell", which `Status` lacks; the
        // evaluator does not need one: an `Err` is that third value, and `undecided_gate` uses it to fail such a rule
        // closed. The kind-mismatch half stays open, tracked in `docs/KNOWN_ISSUES.md`, because closing
        // it needs the registry rules that depend on the current reading changed first -- a
        // precondition, not an impossibility. `Size > 10` against `Size: "50"` is still the quiet wrong
        // answer whether it is spelled as a condition or as a filter, and this arm only makes it
        // legible; it does not make it enforce.
        Some(RecordType::ClauseValueCheck(ClauseCheck::Comparison(ComparisonClauseCheck {
            status: Status::FAIL,
            message: Some(explanation),
            ..
        }))) => Some(match reached {
            ReachedThrough::Condition => format!(
                "the rule did not apply because one of its conditions was not met; a comparison it \
                 made reported: {}",
                explanation
            ),
            ReachedThrough::Filter => format!(
                "the rule did not apply; a comparison in one of its query filters reported: {}",
                explanation
            ),
            ReachedThrough::Neither => {
                format!(
                    "the rule did not apply; a comparison it made reported: {}",
                    explanation
                )
            }
        }),

        _ => None,
    }
}

pub(crate) type Metadata = HashMap<String, String>;

/// A rules file the parser rejected, named so a machine-readable report can say a policy could not
/// be read.
///
/// A file that fails to parse contributes no rules, so it puts nothing in `not_compliant`,
/// `not_applicable` or `compliant` -- and those three lists are empty on a clean run too. Without
/// this the two are the same document, and the exit code is the only thing that tells them apart.
///
/// Deliberately not one of the three verdict lists and not a `status`: a rules file that failed to
/// parse is not a rule that skipped, and filing it as one is the confusion this exists to end.
#[derive(Clone, Debug, Serialize, Default)]
pub(crate) struct RuleFileError {
    pub(crate) file_name: String,
    pub(crate) error: String,
}

#[derive(Clone, Debug, Serialize, Default)]
pub(crate) struct FileReport<'value> {
    pub(crate) name: &'value str,
    pub(crate) metadata: Metadata,
    pub(crate) status: Status,
    #[serde(with = "serde_yaml::with::singleton_map_recursive")]
    pub(crate) not_compliant: Vec<ClauseReport<'value>>,
    pub(crate) not_applicable: BTreeSet<String>,
    /// Why each inapplicable rule did not apply, for the ones where the evaluator knows something
    /// a bare "not applicable" does not convey. Omitted when empty, so a run with nothing to
    /// explain serialises to exactly the document consumers parse today.
    #[serde(skip_serializing_if = "BTreeMap::is_empty")]
    pub(crate) not_applicable_reasons: BTreeMap<String, String>,
    pub(crate) compliant: BTreeSet<String>,
    /// Rules files that could not be read at all. See [`RuleFileError`]. Omitted when empty, for
    /// the same reason `not_applicable_reasons` is: a run whose rules all parsed serialises to
    /// exactly the document consumers parse today.
    ///
    /// Repeated in every record rather than hoisted above them, because the document is an array of
    /// these and there is nowhere above them to put it. The statement is true per data file anyway:
    /// this file went unchecked by those rules.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub(crate) rule_file_errors: Vec<RuleFileError>,
}

impl<'value> FileReport<'value> {
    pub(crate) fn combine(&mut self, report: FileReport<'value>) {
        if report.name != self.name {
            panic!("Incompatible to merge")
        }
        self.status = self.status.and(report.status);
        self.metadata.extend(report.metadata);
        self.not_compliant.extend(report.not_compliant);
        self.compliant.extend(report.compliant);
        self.not_applicable.extend(report.not_applicable);
        self.not_applicable_reasons
            .extend(report.not_applicable_reasons);
        self.rule_file_errors.extend(report.rule_file_errors);
    }
}

#[derive(Clone, Debug, Serialize, Default)]
pub(crate) struct RuleReport<'value> {
    pub(crate) name: &'value str,
    pub(crate) metadata: Metadata,
    pub(crate) messages: Messages,
    pub(crate) checks: Vec<ClauseReport<'value>>,
}

#[derive(Clone, Debug, Serialize)]
pub(crate) struct UnaryComparison {
    pub(crate) value: Rc<PathAwareValue>,
    pub(crate) comparison: (CmpOperator, bool),
}

#[derive(Clone, Debug, Serialize)]
pub(crate) struct ValueUnResolved {
    pub(crate) value: UnResolved,
    pub(crate) comparison: (CmpOperator, bool),
}

#[derive(Clone, Debug, Serialize)]
pub(crate) enum UnaryCheck {
    UnResolved(ValueUnResolved),
    Resolved(UnaryComparison),
    UnResolvedContext(String),
}

impl ValueComparisons for UnaryCheck {
    fn value_from(&self) -> Option<Rc<PathAwareValue>> {
        match self {
            UnaryCheck::UnResolved(ur) => Some(ur.value.traversed_to.clone()),
            UnaryCheck::Resolved(uc) => Some(uc.value.clone()),
            UnaryCheck::UnResolvedContext(_) => None,
        }
    }
}

#[derive(Clone, Debug, Serialize)]
pub(crate) struct UnaryReport {
    pub(crate) check: UnaryCheck,
    pub(crate) context: String,
    pub(crate) messages: Messages,
}

#[derive(Clone, Debug, Serialize)]
pub(crate) struct BinaryComparison {
    pub(crate) from: Rc<PathAwareValue>,
    pub(crate) to: Rc<PathAwareValue>,
    pub(crate) comparison: (CmpOperator, bool),
}

#[derive(Clone, Debug, Serialize)]
pub(crate) struct InComparison {
    pub(crate) from: Rc<PathAwareValue>,
    pub(crate) to: Vec<Rc<PathAwareValue>>,
    pub(crate) comparison: (CmpOperator, bool),
}

#[derive(Clone, Debug, Serialize)]
pub(crate) enum BinaryCheck {
    UnResolved(ValueUnResolved),
    Resolved(BinaryComparison),
    InResolved(InComparison),
}

impl ValueComparisons for BinaryCheck {
    fn value_from(&self) -> Option<Rc<PathAwareValue>> {
        match self {
            BinaryCheck::UnResolved(vur) => Some(vur.value.traversed_to.clone()),
            BinaryCheck::Resolved(res) => Some(res.from.clone()),
            BinaryCheck::InResolved(inr) => Some(inr.from.clone()),
        }
    }

    fn value_to(&self) -> Option<Rc<PathAwareValue>> {
        match self {
            BinaryCheck::Resolved(bc) => Some(bc.to.clone()),
            _ => None,
        }
    }
}

#[derive(Clone, Debug, Serialize)]
pub(crate) struct BinaryReport {
    pub(crate) context: String,
    pub(crate) messages: Messages,
    pub(crate) check: BinaryCheck,
}

#[derive(Clone, Debug, Serialize)]
pub(crate) enum GuardClauseReport {
    Unary(UnaryReport),
    Binary(BinaryReport),
}

impl GuardClauseReport {
    fn get_message(&self) -> Messages {
        match self {
            GuardClauseReport::Unary(unary_report) => unary_report.messages.clone(),
            GuardClauseReport::Binary(binary_report) => binary_report.messages.clone(),
        }
    }
}

pub(crate) trait ValueComparisons {
    fn value_from(&self) -> Option<Rc<PathAwareValue>>;
    fn value_to(&self) -> Option<Rc<PathAwareValue>> {
        None
    }
}

impl ValueComparisons for GuardClauseReport {
    fn value_from(&self) -> Option<Rc<PathAwareValue>> {
        match self {
            GuardClauseReport::Binary(br) => br.check.value_from(),
            GuardClauseReport::Unary(ur) => ur.check.value_from(),
        }
    }

    fn value_to(&self) -> Option<Rc<PathAwareValue>> {
        match self {
            GuardClauseReport::Binary(br) => br.check.value_to(),
            GuardClauseReport::Unary(ur) => ur.check.value_to(),
        }
    }
}

#[derive(Clone, Debug, Serialize)]
pub(crate) struct DisjunctionsReport<'value> {
    pub(crate) checks: Vec<ClauseReport<'value>>,
}

#[derive(Clone, Debug, Serialize)]
pub(crate) struct GuardBlockReport {
    pub(crate) context: String,
    pub(crate) messages: Messages,
    pub(crate) unresolved: Option<UnResolved>,
}

impl ValueComparisons for GuardBlockReport {
    fn value_from(&self) -> Option<Rc<PathAwareValue>> {
        if let Some(ur) = &self.unresolved {
            return Some(ur.traversed_to.clone());
        }
        None
    }
}

#[derive(Clone, Debug, Serialize)]
pub(crate) enum ClauseReport<'value> {
    Rule(RuleReport<'value>),
    Block(GuardBlockReport),
    Disjunctions(DisjunctionsReport<'value>),
    Clause(GuardClauseReport),
}

impl<'value> ClauseReport<'value> {
    pub(crate) fn key(&self, parent: &str) -> String {
        match self {
            Self::Rule(RuleReport { name, .. }) => format!("{}/{}", parent, name),
            Self::Block(_) => format!("{}/B[{:p}]", parent, self),
            Self::Disjunctions(_) => format!("{}/Or[{:p}]", parent, self),
            Self::Clause(_) => format!("{}/C[{:p}]", parent, self),
        }
    }

    pub fn get_message(&self) -> Vec<Messages> {
        match self {
            ClauseReport::Rule(rule) => rule.checks.iter().fold(vec![], |mut messages, report| {
                messages.append(&mut report.get_message());
                messages
            }),
            ClauseReport::Block(block) => vec![block.messages.clone()],
            ClauseReport::Disjunctions(disjunctions) => {
                disjunctions
                    .checks
                    .iter()
                    .fold(vec![], |mut messages, report| {
                        messages.append(&mut report.get_message());
                        messages
                    })
            }
            ClauseReport::Clause(clause) => vec![clause.get_message()],
        }
    }
}

impl<'value> ValueComparisons for ClauseReport<'value> {
    fn value_from(&self) -> Option<Rc<PathAwareValue>> {
        match self {
            Self::Block(b) => b.value_from(),
            Self::Clause(c) => c.value_from(),
            _ => None,
        }
    }

    fn value_to(&self) -> Option<Rc<PathAwareValue>> {
        match self {
            Self::Block(b) => b.value_to(),
            Self::Clause(c) => c.value_to(),
            _ => None,
        }
    }
}

pub(crate) fn cmp_str(cmp: (CmpOperator, bool)) -> &'static str {
    let (cmp, not) = cmp;
    if cmp.is_unary() {
        match cmp {
            CmpOperator::Exists => {
                if not {
                    "NOT EXISTS"
                } else {
                    "EXISTS"
                }
            }
            CmpOperator::Empty => {
                if not {
                    "NOT EMPTY"
                } else {
                    "EMPTY"
                }
            }
            CmpOperator::IsList => {
                if not {
                    "NOT LIST"
                } else {
                    "IS LIST"
                }
            }
            CmpOperator::IsMap => {
                if not {
                    "NOT STRUCT"
                } else {
                    "IS STRUCT"
                }
            }
            CmpOperator::IsString => {
                if not {
                    "NOT STRING"
                } else {
                    "IS STRING"
                }
            }
            CmpOperator::IsFloat => {
                if not {
                    "NOT FLOAT"
                } else {
                    "IS FLOAT"
                }
            }
            CmpOperator::IsNull => {
                if not {
                    "NOT NULL"
                } else {
                    "IS NULL"
                }
            }
            CmpOperator::IsBool => {
                if not {
                    "NOT BOOL"
                } else {
                    "IS BOOl"
                }
            }
            CmpOperator::IsInt => {
                if not {
                    "NOT INT"
                } else {
                    "IS INT"
                }
            }
            _ => unreachable!(),
        }
    } else {
        match cmp {
            CmpOperator::Eq => {
                if not {
                    "NOT EQUAL"
                } else {
                    "EQUAL"
                }
            }
            CmpOperator::Le => {
                if not {
                    "NOT LESS THAN EQUAL"
                } else {
                    "LESS THAN EQUAL"
                }
            }
            CmpOperator::Lt => {
                if not {
                    "NOT LESS THAN"
                } else {
                    "LESS THAN"
                }
            }
            CmpOperator::Ge => {
                if not {
                    "NOT GREATER THAN EQUAL"
                } else {
                    "GREATER THAN EQUAL"
                }
            }
            CmpOperator::Gt => {
                if not {
                    "NOT GREATER THAN"
                } else {
                    "GREATER THAN"
                }
            }
            CmpOperator::In => {
                if not {
                    "NOT IN"
                } else {
                    "IN"
                }
            }
            _ => unreachable!(),
        }
    }
}

fn report_all_failed_clauses_for_rules<'value>(
    checks: &[EventRecord<'value>],
) -> Vec<ClauseReport<'value>> {
    let mut clauses = Vec::with_capacity(checks.len());
    for current in checks {
        match &current.container {
            Some(RecordType::RuleCheck(NamedStatus {
                name,
                status: Status::FAIL,
                message,
                refusal,
            })) => {
                clauses.push(ClauseReport::Rule(RuleReport {
                    name,
                    checks: report_all_failed_clauses_for_rules(&current.children),
                    messages: Messages {
                        custom_message: message.clone(),
                        error_message: None,
                        location: None,
                        refusal: *refusal,
                    },
                    ..Default::default()
                }));
            }

            Some(RecordType::BlockGuardCheck(BlockCheck {
                status: Status::FAIL,
                message,
                refusal,
                ..
            })) => {
                if current.children.is_empty() {
                    clauses.push(ClauseReport::Block(GuardBlockReport {
                        context: current.context.clone(),
                        messages: Messages {
                            // The record's own explanation when it carries one, with the generic
                            // sentence below only as the fallback: ignoring `message` would report a
                            // block that said precisely why it failed as though it had merely
                            // selected nothing.
                            error_message: Some(message.clone().unwrap_or_else(|| {
                                String::from("query for block clause did not retrieve any value")
                            })),
                            custom_message: None,
                            location: None,
                            refusal: *refusal,
                        },
                        unresolved: None,
                    }));
                } else {
                    clauses.extend(report_all_failed_clauses_for_rules(&current.children));
                }
            }

            // A disjunction records a message on one path in `eval_conjunction_clauses`: every
            // disjunct ran, none passed, and at least one could not be evaluated, so the error that
            // was held is returned with that sentence. The other error path, an error outside the
            // hold's allow-list, returns at once with `message: None`, because that error leaves
            // `eval_rules_file` before any reporter reads the tree (the explanation-site count in
            // `eval_tests.rs` is what keeps an unrendered message from being added there). Reported
            // as a block rather than as an empty `Disjunctions`, for the same reason as the arms
            // below: an empty list of checks tells the reader nothing, and the message is the only
            // account of what went wrong.
            Some(RecordType::Disjunction(BlockCheck {
                status: Status::FAIL,
                message,
                refusal,
                ..
            })) => {
                let nested = report_all_failed_clauses_for_rules(&current.children);
                if nested.is_empty() {
                    if let Some(explanation) = message {
                        clauses.push(ClauseReport::Block(GuardBlockReport {
                            context: current.context.clone(),
                            messages: Messages {
                                error_message: Some(explanation.clone()),
                                custom_message: None,
                                location: None,
                                refusal: *refusal,
                            },
                            unresolved: None,
                        }));
                    }
                    continue;
                }
                clauses.push(ClauseReport::Disjunctions(DisjunctionsReport {
                    checks: nested,
                }));
            }

            // These four recurse into their children for the per-value detail. Each can also carry
            // a message of its own, which is read rather than discarded: an arm matching with `..`,
            // ignoring the field, would report whatever the children produced.
            //
            // Nothing is what the children produce when the clause failed *because* there was
            // nothing to compare. An empty-reference comparison records its explanation here and
            // has no per-value results by construction, so the report came back empty, the console
            // printed "Number of non-compliant resources 0", and the structured output carried
            // "checks": [] with a null error_message -- for a run that had correctly exited 19.
            //
            // So: recurse when the children have something to say, and fall back to this record's
            // own message when they do not. A failing clause always explains itself somewhere.
            Some(RecordType::GuardClauseBlockCheck(BlockCheck {
                status: Status::FAIL,
                message,
                refusal,
                ..
            }))
            | Some(RecordType::TypeCheck(TypeBlockCheck {
                block:
                    BlockCheck {
                        status: Status::FAIL,
                        message,
                        refusal,
                        ..
                    },
                ..
            }))
            | Some(RecordType::WhenCheck(BlockCheck {
                status: Status::FAIL,
                message,
                refusal,
                ..
            })) => {
                let nested = report_all_failed_clauses_for_rules(&current.children);
                if nested.is_empty() {
                    if let Some(explanation) = message {
                        clauses.push(ClauseReport::Block(GuardBlockReport {
                            context: current.context.clone(),
                            messages: Messages {
                                error_message: Some(explanation.clone()),
                                custom_message: None,
                                location: None,
                                refusal: *refusal,
                            },
                            unresolved: None,
                        }));
                    }
                } else {
                    clauses.extend(nested);
                }
            }

            // TypeBlock carries a bare Status with no message, so there is nothing to fall back to.
            Some(RecordType::TypeBlock(Status::FAIL)) => {
                clauses.extend(report_all_failed_clauses_for_rules(&current.children));
            }

            Some(RecordType::ClauseValueCheck(clause)) => match clause {
                ClauseCheck::NoValueForEmptyCheck(check) => {
                    let custom_message = check
                        .custom_message
                        .as_ref()
                        .map_or("".to_string(), |s| s.replace('\n', ";"));

                    // Says what happened, which it did not. The text was hardcoded as "was not empty" and
                    // this check is reached from both polarities, so a `!EMPTY` clause that failed *because
                    // its selection was empty* reported that the selection was not empty -- the negation of
                    // the reason. Harmless while nothing printed it; the console reporter now does, and a
                    // section whose whole purpose is to say why must not ship the opposite of why.
                    //
                    // The clause selected nothing either way, so that is what the message says, and the
                    // operator it failed is already in the context beside it. The query named is the one
                    // the record carries, with its filters spelled out, rather than the clause's own
                    // rendering, which stands `(filter-clauses)` in for every filter and so gave two
                    // clauses that filter one collection differently the same sentence.
                    let error_message = format!(
                        "Check was not compliant as the query [{}] selected no values to test",
                        check.query
                    );
                    clauses.push(ClauseReport::Clause(GuardClauseReport::Unary(
                        UnaryReport {
                            context: current.context.clone(),
                            check: UnaryCheck::UnResolvedContext(current.context.to_string()),
                            messages: Messages {
                                custom_message: Some(custom_message),
                                error_message: Some(error_message),
                                location: None,
                                refusal: false,
                            },
                        },
                    )))
                }

                ClauseCheck::Success => {}

                ClauseCheck::DependentRule(missing) => {
                    let message = missing.custom_message.as_ref().map_or("", String::as_str);
                    let error_message = format!(
                            "Check was not compliant as dependent rule [{rule}] did not PASS. Context [{cxt}]",
                            rule=missing.rule,
                            cxt=current.context,
                        );
                    clauses.push(ClauseReport::Clause(GuardClauseReport::Unary(
                        UnaryReport {
                            messages: Messages {
                                custom_message: Some(message.to_string()),
                                error_message: Some(error_message),
                                location: None,
                                refusal: false,
                            },
                            context: current.context.clone(),
                            check: UnaryCheck::UnResolvedContext(missing.rule.to_string()),
                        },
                    )));
                }

                ClauseCheck::MissingBlockValue(missing) => {
                    let (property, far, ur) = match &missing.from {
                        QueryResult::UnResolved(ur) => {
                            (ur.remaining_query.as_str(), ur.traversed_to.clone(), ur)
                        }
                        _ => unreachable!(),
                    };
                    let message = missing.custom_message.as_ref().map_or("", String::as_str);
                    let error_message = format!(
                            "Check was not compliant as property [{}] is missing. Value traversed to [{}]",
                            property,
                            far
                        );
                    clauses.push(ClauseReport::Block(GuardBlockReport {
                        context: current.context.clone(),
                        messages: Messages {
                            custom_message: Some(message.to_string()),
                            error_message: Some(error_message),
                            location: None,
                            refusal: false,
                        },
                        unresolved: Some(ur.clone()),
                    }));
                }

                ClauseCheck::Unary(UnaryValueCheck {
                    comparison: (cmp, not),
                    value:
                        ValueCheck {
                            status: Status::FAIL,
                            from,
                            message,
                            custom_message,
                            refusal,
                        },
                }) => {
                    use CmpOperator::*;
                    let cmp_msg = match cmp {
                        Exists => {
                            if *not {
                                "existed"
                            } else {
                                "did not exist"
                            }
                        }
                        Empty => {
                            if *not {
                                "was empty"
                            } else {
                                "was not empty"
                            }
                        }
                        IsList => {
                            if *not {
                                "was a list "
                            } else {
                                "was not list"
                            }
                        }
                        IsMap => {
                            if *not {
                                "was a struct"
                            } else {
                                "was not struct"
                            }
                        }
                        IsString => {
                            if *not {
                                "was a string "
                            } else {
                                "was not string"
                            }
                        }
                        IsInt => {
                            if *not {
                                "was int"
                            } else {
                                "was not int"
                            }
                        }
                        IsBool => {
                            if *not {
                                "was bool"
                            } else {
                                "was not bool"
                            }
                        }
                        IsNull => {
                            if *not {
                                "was null"
                            } else {
                                "was not null"
                            }
                        }
                        _ => {
                            if *not {
                                "was float"
                            } else {
                                "was not float"
                            }
                        }
                    };

                    let custom_message = custom_message
                        .as_ref()
                        .map_or(String::default(), |s| s.to_string());

                    let error_message = message
                        .as_ref()
                        .map_or("".to_string(), |s| format!("Error = [{}]", s));

                    // The report's message is the record's message inside a sentence, and the kind
                    // the report carries describes that sentence, not the record's: a sentence that
                    // interpolates nothing from the template beyond a path keeps the record's kind,
                    // and one that interpolates a value the query traversed to is no refusal whatever
                    // the record says, because the console prints a refusal whole and such a value
                    // has no length to clear (`reporters::validate::common::bounded_for_the_console`).
                    let (message, check, refusal) = match from {
                            // A literal reaches here through `let x = 5` followed by a unary check
                            // such as `%x empty`: the operator has no answer for a number, the
                            // clause fails, and this is the message that failure carries. It was
                            // `unreachable!()`, so building the report took the process down at exit
                            // 101 in all four output modes. String and list literals never reached
                            // it, because the operator answers those.
                            //
                            // Reported as a resolved value, which is what it is -- the two variants
                            // carry the same payload, and the only difference is that a literal's
                            // path is the unlocated root.
                            QueryResult::Literal(res) | QueryResult::Resolved(res) => {
                                (
                                    format!(
                                        "Check was not compliant as property [{prop}] {cmp_msg}.{err}",
                                        prop=res.self_path(),
                                        cmp_msg=cmp_msg,
                                        err=error_message
                                    ),
                                    UnaryCheck::Resolved(UnaryComparison {
                                        comparison: (*cmp, *not),
                                        value: res.clone(),
                                    }),
                                    *refusal,
                                )

                            },

                            // The value traversed to is printed into the sentence, so the sentence
                            // carries a template value even when the error it embeds is a refusal.
                            QueryResult::UnResolved(unres) => {
                                (
                                    format!(
                                        "Check was not compliant as property [{remain}] is missing. Value traversed to [{tr}].{err}",
                                        remain=unres.remaining_query,
                                        tr=unres.traversed_to,
                                        err=error_message
                                    ),
                                    UnaryCheck::UnResolved(ValueUnResolved{
                                        value: unres.clone(),
                                        comparison: (*cmp, *not),
                                    }),
                                    false,
                                )
                            }
                        };

                    clauses.push(ClauseReport::Clause(GuardClauseReport::Unary(
                        UnaryReport {
                            messages: Messages {
                                custom_message: Some(custom_message),
                                error_message: Some(message),
                                location: Some(
                                    from.unresolved_traversed_to()
                                        .map_or(Location::default(), |val| val.self_path().1),
                                ),
                                refusal,
                            },
                            context: current.context.clone(),
                            check,
                        },
                    )));
                }

                ClauseCheck::Comparison(ComparisonClauseCheck {
                    custom_message,
                    message,
                    comparison: (cmp, not),
                    from,
                    status: Status::FAIL,
                    to,
                    refusal,
                }) => {
                    let custom_message = custom_message
                        .as_ref()
                        .map_or(String::default(), |s| s.to_string());

                    let error_message = message
                        .as_ref()
                        .map_or("".to_string(), |s| format!(" Error = [{}]", s));

                    // The record's own kind travels with the sentence in every arm below
                    // (`ComparisonClauseCheck::refusal`): the sentence names the value the query
                    // traversed to beside the record's message, as the sentences of the other clause
                    // records do, and the console reads the kind to print a refusal's remedy and path
                    // whole where it cuts the rest. In a refusal's sentence every value quoted from
                    // the template (the value a query traversed to, the two values a comparison
                    // decided) is bounded as every template part of a refusal is
                    // (`bounded_traversed_to`): printed whole, a document the query failed at the root
                    // of, or a long right-hand value beside an empty left-hand collection, would fill
                    // the refusal's bound and the sentence would carry the document.
                    let refusal = *refusal;
                    let rendered = |value: &PathAwareValue| match refusal {
                        true => bounded_traversed_to(value),
                        false => value.to_string(),
                    };
                    match from {
                        QueryResult::Literal(_) => unreachable!(),
                        QueryResult::UnResolved(to_unres) => {
                            // A left-hand side the evaluator REFUSED to read, whose record carries the
                            // refusal's text, is named as the refusal (the error the record carries,
                            // printed whole by the console), not as a missing property spelled with
                            // the marker's remaining query, as the right-hand arm below names its
                            // refusal. An absent left-hand value keeps the missing-property sentence.
                            let message = if to_unres.kind.is_refusal() && message.is_some() {
                                format!(
                                    "Check was not compliant as the value to compare from could not be read.{err}",
                                    err=error_message
                                )
                            } else {
                                format!(
                                    "Check was not compliant as property [{remain}] to compare from is missing. Value traversed to [{to}].{err}",
                                    remain=to_unres.remaining_query,
                                    to=rendered(&to_unres.traversed_to),
                                    err=error_message
                                )
                            };
                            clauses.push(ClauseReport::Clause(GuardClauseReport::Binary(
                                BinaryReport {
                                    context: current.context.to_string(),
                                    messages: Messages {
                                        custom_message: Some(custom_message),
                                        error_message: Some(message),
                                        location: Some(to_unres.traversed_to.self_path().1),
                                        refusal,
                                    },
                                    check: BinaryCheck::UnResolved(ValueUnResolved {
                                        comparison: (*cmp, *not),
                                        value: to_unres.clone(),
                                    }),
                                },
                            )));
                        }

                        QueryResult::Resolved(res) => {
                            if let Some(to) = to {
                                match to {
                                    QueryResult::Literal(_) => unreachable!(),
                                    QueryResult::Resolved(to_res) => {
                                        let message = format!(
                                                "Check was not compliant as property value [{from}] {op_msg} value [{to}].{err}",
                                                from=rendered(res),
                                                to=rendered(to_res),
                                                op_msg=match cmp {
                                                    CmpOperator::Eq => if *not { "equal to" } else { "not equal to" },
                                                    CmpOperator::Le => if *not { "less than equal to" } else { "not less than equal to" },
                                                    CmpOperator::Lt => if *not { "less than" } else { "not less than" },
                                                    CmpOperator::Ge => if *not { "greater than equal to" } else { "not greater than equal" },
                                                    CmpOperator::Gt => if *not { "greater than" } else { "not greater than" },
                                                    CmpOperator::In => if *not { "in" } else { "not in" },
                                                    _ => unreachable!()
                                                },
                                                err=error_message
                                            );
                                        clauses.push(ClauseReport::Clause(
                                            GuardClauseReport::Binary(BinaryReport {
                                                check: BinaryCheck::Resolved(BinaryComparison {
                                                    to: to_res.clone(),
                                                    from: res.clone(),
                                                    comparison: (*cmp, *not),
                                                }),
                                                context: current.context.to_string(),
                                                messages: Messages {
                                                    location: Some(to_res.clone().self_path().1),
                                                    error_message: Some(message),
                                                    custom_message: Some(custom_message),
                                                    refusal,
                                                },
                                            }),
                                        ))
                                    }

                                    QueryResult::UnResolved(to_unres) => {
                                        // A right-hand side the evaluator REFUSED to read is not a
                                        // property the template lacks: its sentence names the refusal
                                        // (the error the record carries, printed whole by the console),
                                        // not a missing property spelled with the marker's remaining
                                        // query. An absent right-hand value keeps the missing-property
                                        // sentence.
                                        let message = if refusal {
                                            format!(
                                                "Check was not compliant as the value to compare to could not be read.{err}",
                                                err=error_message
                                            )
                                        } else {
                                            format!(
                                                "Check was not compliant as property [{remain}] to compare to is missing. Value traversed to [{to}].{err}",
                                                remain=to_unres.remaining_query,
                                                to=rendered(&to_unres.traversed_to),
                                                err=error_message
                                            )
                                        };
                                        clauses.push(ClauseReport::Clause(
                                            GuardClauseReport::Binary(BinaryReport {
                                                context: current.context.to_string(),
                                                messages: Messages {
                                                    custom_message: Some(custom_message),
                                                    error_message: Some(message),
                                                    location: Some(
                                                        to_unres.traversed_to.self_path().1,
                                                    ),
                                                    refusal,
                                                },
                                                check: BinaryCheck::UnResolved(ValueUnResolved {
                                                    comparison: (*cmp, *not),
                                                    value: to_unres.clone(),
                                                }),
                                            }),
                                        ));
                                    }
                                }
                            }
                        }
                    }
                }

                // `message` is bound rather than dropped through the `..`, and appended in the same
                // `Error = [...]` shape the `ClauseCheck::Comparison` arm below uses. This is the
                // structured half of the same defect: the console reporters read
                // `InComparisonCheck::message` through `NameInfo`, so populating it in `report_by_lhs`
                // is enough for them, but this reporter builds its own sentence and had no slot for a
                // reason at all. Without this, `-o json` and the FFI and Lambda paths -- which have no
                // stderr channel and so have the report as their only record -- still say only "was
                // not present in".
                ClauseCheck::InComparison(check) if check.status == Status::FAIL => {
                    let InComparisonCheck {
                        from,
                        to,
                        custom_message,
                        comparison,
                        ..
                    } = check;
                    // One sentence per lead clause, and the lead is decided once, on the record, by
                    // `InComparisonCheck::lead`, the same decision the console renderers format from.
                    // "was not present in" asserts that the membership question was answered, which is
                    // right for a decided failure and false for one the comparison never reached, so a
                    // reason outranks the operator: a refused pairing and a right-hand value the query
                    // could not reach both read as not compared, under `IN`, `NOT IN`, `==` and `!=`
                    // alike. A key filter's `==` or `!=` against a set reads as the equality it is: a
                    // failed `==` was equal to none of the set, and a failed `!=` was equal to the
                    // elements the lead names, stated rather than the whole set so no pair the
                    // comparison did not answer that way is claimed. A decided membership failure
                    // keeps its wording to the byte.
                    let resolved_from = from.resolved().unwrap();
                    let subject = resolved_from.self_path();
                    let error_message = match check.lead() {
                        MembershipLead::NotCompared(reason) => format!(
                            "Check was not compliant as property [{}] could not be compared with [{}]. Error = [{}]",
                            subject,
                            SliceDisplay(to),
                            reason
                        ),
                        MembershipLead::NotEqualToAny => format!(
                            "Check was not compliant as property [{}] is not equal to any of [{}]",
                            subject,
                            SliceDisplay(to)
                        ),
                        MembershipLead::EqualTo(matched) => format!(
                            "Check was not compliant as property [{}] is equal to [{}], one of [{}]",
                            subject,
                            SliceDisplay(&matched),
                            SliceDisplay(to)
                        ),
                        MembershipLead::Membership => format!(
                            "Check was not compliant as property [{}] was not present in [{}]",
                            subject,
                            SliceDisplay(to)
                        ),
                    };
                    clauses.push(ClauseReport::Clause(GuardClauseReport::Binary(
                        BinaryReport {
                            context: current.context.to_string(),
                            messages: Messages {
                                custom_message: custom_message.clone(),
                                error_message: Some(error_message),
                                location: Some(from.resolved().unwrap().self_path().1),
                                // The record's own kind (`InComparisonCheck::refusal`), as the
                                // `Comparison` arm copies its record's.
                                refusal: check.refusal,
                            },
                            check: BinaryCheck::InResolved(InComparison {
                                from: match from.resolved() {
                                    Some(val) => val,
                                    None => match from.unresolved_traversed_to() {
                                        Some(val) => val,
                                        None => unreachable!(),
                                    },
                                },
                                to: to
                                    .iter()
                                    .filter(|t| matches!(t, QueryResult::Resolved(_)))
                                    .map(|t| match t {
                                        QueryResult::Resolved(v) => v.clone(),
                                        _ => unreachable!(),
                                    })
                                    .collect::<Vec<_>>(),
                                comparison: *comparison,
                            }),
                        },
                    )));
                }

                _ => {}
            },

            _ => {}
        }
    }
    clauses
}

pub(crate) fn simplified_json_from_root<'value>(
    root: &EventRecord<'value>,
) -> Result<FileReport<'value>> {
    Ok(match &root.container {
        Some(RecordType::FileCheck(NamedStatus { name, status, .. })) => {
            let mut pass: BTreeSet<String> = BTreeSet::new();
            let mut skip: BTreeSet<String> = BTreeSet::new();
            let mut skip_reasons: BTreeMap<String, String> = BTreeMap::new();
            for each in &root.children {
                if let Some(RecordType::RuleCheck(NamedStatus { status, name, .. })) =
                    &each.container
                {
                    match *status {
                        Status::PASS => {
                            pass.insert(name.to_string());
                        }
                        SKIP => {
                            skip.insert(name.to_string());
                            if let Some(reason) = find_skip_reason(each) {
                                skip_reasons.insert(name.to_string(), reason);
                            }
                        }
                        _ => {}
                    }
                }
            }
            FileReport {
                status: *status,
                name,
                not_compliant: report_all_failed_clauses_for_rules(&root.children),
                not_applicable: skip,
                not_applicable_reasons: skip_reasons,
                compliant: pass,
                ..Default::default()
            }
        }
        _ => unreachable!(),
    })
}

pub(crate) fn resolve_function<'value, 'eval, 'loc: 'value>(
    function: &'value FunctionExpr<'loc>,
    resolver: &'eval mut dyn EvalContext<'value, 'loc>,
) -> Result<Vec<QueryResult>> {
    Ok(resolve_function_tagged(function, resolver)?.0)
}

/// `resolve_function`, reporting as well where the call's results enumerate: the shape retrieval reported
/// for the one argument the function maps over ([`FunctionName::mapped_argument`]), because
/// `to_lower(Types[*])` is as many strings as `Types[*]` and enumerates where it does, or an entry set
/// when that argument held a list the function read element by element, because `to_lower(Types)` is
/// then as many strings as `Types` has entries. A folding function (`join`, `count`) produces one value
/// whatever its arguments did, and a scalar argument (`regex_replace`'s pattern) has to resolve to one
/// value, so it never enumerates. The third answer is the result's record ([`PassedOn::computed_from`]):
/// the notes of the empty selections the call read, which a binding to the call keeps so that every read
/// of the binding counts as a read of those selections. Read by `IN` for a call on its right-hand side,
/// by the scopes for a `let` bound to a call, and by a parameterized call for a call passed as an
/// argument, each with the resolver the call is written in.
pub(crate) fn resolve_function_with_shape<'value, 'eval, 'loc: 'value>(
    function: &'value FunctionExpr<'loc>,
    resolver: &'eval mut dyn EvalContext<'value, 'loc>,
) -> Result<(Vec<QueryResult>, RhsEnumeration, PassedOn)> {
    let (results, _, shape, read_from) = resolve_function_tagged(function, resolver)?;
    Ok((results, shape, PassedOn::computed_from(read_from)))
}

/// The reason a function call is refused for its arguments before any function runs: the first argument
/// entry that is the marker a key filter leaves for a map it could not decide, read through
/// `eval::undecidable_reason` (the reason the filter recorded, or the path when it recorded none), and
/// `None` when no entry is that marker. One reader for the marker, so the dispatch and the operators
/// report a marker recorded without a reason in the same words.
pub(crate) fn undecidable_argument_reason(args: &[Vec<QueryResult>]) -> Option<String> {
    args.iter().flatten().find_map(|entry| match entry {
        QueryResult::UnResolved(unresolved) => super::eval::undecidable_reason(unresolved),
        QueryResult::Resolved(_) | QueryResult::Literal(_) => None,
    })
}

/// The one resolution behind `resolve_function` and `resolve_function_with_shape`: the call's results,
/// whether the call was a literal, where its results enumerate, and the notes of the empty selections
/// the call read (`PassedOn::read_from`).
///
/// A call is a literal when every argument was: a `LetValue::Value` is one; a query is one when it is a
/// `%var` bound to a literal, which is the only way a query answers `Literal` results; a nested call is one
/// when this says so of it. The tag is decided from the arguments, never from the elements that came back:
/// an empty selection has no elements to read a tag from and is a query over the data, so it is not
/// literal, and `count(%empty)` stays `Resolved`. A call with no arguments is not literal either -- `now()`
/// reads nothing from the rules file; it is a value computed at evaluation time.
fn resolve_function_tagged<'value, 'eval, 'loc: 'value>(
    function: &'value FunctionExpr<'loc>,
    resolver: &'eval mut dyn EvalContext<'value, 'loc>,
) -> Result<(Vec<QueryResult>, bool, RhsEnumeration, Vec<LacksKeysNote>)> {
    count_function_resolution();
    let FunctionExpr {
        name,
        parameters,
        location,
    } = function;
    let mapped = name.mapped_argument();
    let mut shape = RhsEnumeration::Names;
    let mut args: Vec<Vec<QueryResult>> = Vec::with_capacity(parameters.len());
    let mut as_produced: Vec<Vec<QueryResult>> = Vec::with_capacity(parameters.len());
    let mut literal_arguments = Vec::with_capacity(parameters.len());
    let mut any_expanded = false;
    // The notes of the empty selections the call reads: an argument that is such a selection handed on
    // bare, an argument whose binding's value was computed from one, a nested call's. Returned as the
    // result's `PassedOn::read_from`, so a `let` bound to the call carries them and every later read of
    // the binding counts as a read of the selection.
    let mut read_from: Vec<LacksKeysNote> = Vec::new();
    let in_predicate = resolver.in_predicate();
    for (index, param) in parameters.iter().enumerate() {
        // A list value denotes its elements, one level deep, as it does on the comparison path --
        // when the argument did not already enumerate.
        //
        // The results went to the function as the query produced them, and a property holding a list,
        // or a `let` bound to a list literal, is one result holding a `List`. So `count(Props.L)` over
        // `L: [a, b, c]` was 1, `join(%lit, ",")` over `let lit = ["a", "b", "c"]` refused the list as
        // a non-string value, and `parse_int(Props.Ports)` over `Ports: ["80"]` resolved to nothing --
        // while `Props.L == ["a", "b", "c"]` on the same data compared element-wise and passed. The
        // author had to know to write `[*]` for a function and not for an operator.
        //
        // `interpolated_keys` is the expansion the comparison path already applies to its right-hand
        // values, reused so the two read a list the same way: one level, and a list inside a list stays
        // one element. A literal is expanded, and so is a query that descends to a key, since each
        // result is then the whole value the key holds. A query that projects (`Props.*`, `L[*]`, a
        // filter) is not: it already enumerated, each result is one member, and a member that happens to
        // be a list is one value -- `count(%template.Properties.*)` counts properties when one of them
        // is a list, and `count(Nested[*])` counts the inner lists. `query_projects` is the reading the
        // filter path already makes of the same question. A nested call's answers are read the same
        // way as a `let` bound to that call: `count(json_parse(%s))` and `let p = json_parse(%s)` then
        // `count(%p)` are one spelling apart and answered 1 and 3 over `'[1, 2, 3]'` when the nested
        // form was left alone. A scalar argument given a one-element list reads as that element, and
        // one given a longer list is refused by the arity check in its `call`. The unexpanded values
        // are kept beside the expanded ones (`as_produced`), for the notice below.
        //
        // Whether the expansion changed anything is read off the produced values as they are built
        // (`holds_a_list`: a list among them is the one thing `interpolated_keys` rewrites), not by
        // comparing the two vectors afterwards: an argument that does not enumerate is a fresh copy
        // of what the query produced, so the comparison walked the whole value -- the whole template,
        // for `count(Resources)` -- once per evaluation, once per resource inside a block.
        let (produced, values, literal, produced_shape, expanded_here) = match param {
            LetValue::Value(value) => {
                let produced = vec![QueryResult::Literal(Rc::new(value.clone()))];
                let expanded_here = holds_a_list(&produced);
                let expanded = interpolated_keys(&produced);
                (
                    produced,
                    expanded,
                    true,
                    RhsEnumeration::Names,
                    expanded_here,
                )
            }
            LetValue::AccessClause(clause) => {
                let (mut produced, resolved_shape, passed_on) =
                    resolver.query_with_shape(&clause.query)?;
                // An argument that is the empty selection a one-object filter left, handed on bare
                // (`count(this)` in a block body running over it, `count(%v)` over `let v = this`,
                // `count(Resources.*.Properties.Tags[*][ Key == 'Env' ])` bound by a `let`): the read is
                // decided here as the unary clause's bare read is (`refuse_bare_read`), the rule
                // `docs/KNOWN_ISSUES.md` states for the call. Over an object that holds an entry the
                // predicate compared against, or whose list twin could not be evaluated, the read is
                // REFUSED, since the function would otherwise count 0 where the twin counts the pair
                // (`{ let n = count(this)  %n >= 1 }` over `{ Env: { Ref: P }, Team: platform }` under
                // `[ Key == 'Env' ]`, where `{ this !empty }` is refused); over every other object the
                // selection is kept, the function counts 0 as the twin's empty selection does, and the
                // clause that reads the result has read the selection, so it is not judged as one that
                // decided on nothing read (`EmptySelection::clause_decided`).
                // Inside a predicate the refusal's marker joins the argument, which
                // `undecidable_argument_reason` refuses below; outside one the refusal is the clause's.
                passed_on.read_bare(in_predicate, &mut produced)?;
                read_from.extend(passed_on.lacks_keys().iter().cloned());
                read_from.extend(passed_on.read_from().iter().cloned());
                let literal = !produced.is_empty()
                    && produced
                        .iter()
                        .all(|value| matches!(value, QueryResult::Literal(_)));
                let projects = query_projects(&clause.query, resolver, &mut vec![]);
                let expanded_here = !projects && holds_a_list(&produced);
                let expanded = match projects {
                    true => produced.clone(),
                    false => interpolated_keys(&produced),
                };
                (produced, expanded, literal, resolved_shape, expanded_here)
            }
            LetValue::FunctionCall(nested) => {
                let (produced, literal, resolved_shape, nested_read_from) =
                    resolve_function_tagged(nested, resolver)?;
                read_from.extend(nested_read_from);
                let expanded_here = holds_a_list(&produced);
                let expanded = interpolated_keys(&produced);
                (produced, expanded, literal, resolved_shape, expanded_here)
            }
        };
        // The shape is where the values the function reads enumerate. When the expansion left the
        // mapped argument as it was produced, that is where the retrieval said it enumerated: a scalar
        // the query named is one haystack to `IN`, and `Types[*]` enumerated already. When the expansion
        // split a list into its elements, the function reads one value per entry and answers one value
        // per entry, so the call's results are an entry set however the argument's query spelled it.
        // Reported as the query reported it, `to_lower(Mappings.Allowed.Types)` and `to_lower(%allowed)`
        // over `let allowed = ["GP2", "GP3"]` were two strings that each named their value, and `IN`
        // read them as two haystacks: `VolumeType IN to_lower(%allowed)` passed `gp` and the empty
        // string by containment in `gp2`, where the same allowlist without the function is membership.
        if mapped == Some(index) {
            shape = match expanded_here {
                true => RhsEnumeration::LastPart,
                false => produced_shape,
            };
        }
        any_expanded |= expanded_here;
        as_produced.push(produced);
        args.push(values);
        literal_arguments.push(literal);
    }

    // A function over literal arguments only computes a literal, and the result is tagged as one.
    //
    // `is_literal` in `operators.rs` routes a comparison by that tag, and the arm a lone literal takes
    // reports a shape refusal that the queried arm drops, so a `Resolved` result would let
    // `Ports not in parse_int("5")` pass on `Ports: [80, 443]` where `Ports not in 5` fails with
    // "Can not compare": one constant, two verdicts, decided by whether a function spelled it. A `let`
    // bound to a bare literal is `Literal`, and so is a `let` bound to a function of bare literals. The
    // tag also carries provenance into the operators: `parse_int(%s)` after `let s = to_lower("ABC")` is
    // still the author's mistake and stops the run, where the same chain over `to_lower(Resources.X.Type)`
    // is a fact about the data and is held.
    let all_literal = !parameters.is_empty() && literal_arguments.iter().all(|literal| *literal);
    let tag = |value: PathAwareValue| -> QueryResult {
        let value = Rc::new(value);
        match all_literal {
            true => QueryResult::Literal(value),
            false => QueryResult::Resolved(value),
        }
    };

    // One answer per input, with an input the function has no answer for kept as unresolved.
    //
    // The functions answer `Vec<Option<_>>`, one entry per element of their first argument, and `None`
    // for an element they cannot take: a non-string handed to `to_lower`, a key the query did not
    // find. This flattened the `None`s away, so the elements vanished before the comparison and nothing
    // recorded that they had been there. `to_lower(%ingress.IpProtocol) == "tcp"` over an ingress list
    // holding `IpProtocol: -1` compared the one string and passed, while the bare query failed the
    // `-1` as not comparable; the same with an entry that had no `IpProtocol`, which the bare query
    // fails as a missing property. An author who wrapped the query in `to_lower` to be
    // case-insensitive had switched the check off for the values it was written to catch.
    //
    // Kept as an unresolved result rather than refused, because a refusal takes the whole clause down
    // and this is a verdict about one element: the comparison already fails an unresolved element and
    // the report names its path, which is what the bare query does for the same data. The query's own
    // unresolved result is kept as it was, reason included; for a value the function could not take,
    // one is built here naming the function, the input's path and its type.
    //
    // `count` and `join` answer once for the whole selection, so their answer does not line up with
    // the inputs. A `None` from them is pinned on the unresolved input that caused it when there is
    // one, else on the first input.
    //
    // Before any function runs: an argument entry that is the marker a key filter leaves for a map it
    // could not decide (`UnResolvedKind::Undecidable`) is refused here, once, for every function. The
    // functions read an unresolved entry as an input they have no answer for, which is right for a
    // value the document lacks and wrong for this marker: `count` counted past it, so
    // `count(Resources.*.Cfg[ keys == Names[*].Name ])` over one undecidable map beside one decided
    // map answered 1 and `%n == 1` passed at exit 0 with nothing in the run saying a selection could
    // not be decided; `to_lower` kept it as an unresolved entry, a decided no, which a `when` gate read
    // as not applicable. The selection is unknown, not absent, so no answer built over it can be
    // trusted, and the error is the one the key filter's own clause raises, carrying the marker's
    // reason; a `let` bound to the call, a right-hand side, a parameterized argument and a nested call
    // all thread it up as they thread the filter's. The ordinary unresolved entry is left to the
    // functions as before. Inside a filter predicate the marker is built as everywhere else, so a
    // function over an undecidable selection there is refused here too, and the predicate's clause
    // raises: the enclosing clause fails closed rather than deselecting an entry nobody could decide.
    // The marker's kind, and the text for one recorded without a reason, are read by
    // `eval::undecidable_reason`, the one reader the operators use, so the same marker is reported one
    // way wherever it is met (`undecidable_argument_reason`).
    if let Some(reason) = undecidable_argument_reason(&args) {
        return Err(Error::UndecidableComparison(reason));
    }
    let results = name.call(&args)?;
    let aligned = args.first().map_or(0, Vec::len) == results.len();

    // A result that the expansion moved is announced for one release.
    //
    // Every function read a list value as one value before; it reads the elements now, and whatever it
    // answers over them is a different answer: `count(Props.L)` over `[a, b, c]` was 1 and is 3,
    // `parse_int(Props.Ports)` over `["80"]` resolved to nothing and is `[80]`, so a `when %ports
    // !empty` that skipped its body runs it. Measured rather than inferred: when some argument's
    // expanded values differ from the values the query or literal produced (`any_expanded`, read off
    // the produced values above), the function is called once more over the unexpanded values, and a
    // notice is owed when the two answers differ. Once per call site, through the evaluator's notice
    // set, with the first answers seen, so a call inside a block over resources prints one line. A
    // call whose arguments held no list, or whose arguments already enumerated (`[*]`, `.*`, a
    // filter), is never called twice.
    //
    // Only while evaluating, and once per site. Under a measurement (`Measurement::Quiet`,
    // `WithoutUnresolved`) the root records no notice at all, so the second call could not produce the
    // one thing it exists for. A site whose notice is already recorded has nothing left to learn either:
    // `count(Properties.Ports)` inside a type block runs once per matching resource, and the second
    // call would otherwise run for every one of them after the first had recorded the notice. The scope
    // answers `has_deprecation_site` for exactly this question, and the bound-map filter notice is
    // guarded by the same two.
    if any_expanded
        && resolver.measurement() == Measurement::Off
        && !resolver.has_deprecation_site(DeprecationKind::ListArgumentExpansion, location)
    {
        count_list_expansion_probe();
        let before = name.call(&as_produced).ok();
        if before.as_ref() != Some(&results) {
            resolver.record_deprecation_once(
                DeprecationKind::ListArgumentExpansion,
                location,
                list_argument_expansion_notice(function, before.as_deref(), &results),
            );
        }
    }

    Ok((
        results
            .into_iter()
            .enumerate()
            .map(|(index, result)| match result {
                Some(value) => tag(value),
                None => no_answer_for(name, &args, aligned.then_some(index)),
            })
            .collect::<Vec<_>>(),
        all_literal,
        shape,
        read_from,
    ))
}

/// Notice for a function call whose answer moved because a list value among its arguments is now read
/// as its elements.
///
/// Announced for one release, because it moves an answer a rule may depend on: the unexpanded reading
/// hands the function each list as one value, the expanded one hands it the elements. `before` is the answer over
/// the unexpanded values, `None` when the call could not be evaluated over them; `after` is this
/// release's answer. For `count` the two numbers are the counts themselves, and "has no answer" is the
/// case where nothing resolved beside an input the function had no answer for (`no_answer_for` pins
/// its `None` on the entry and the clause fails naming the key). For every other function the text
/// counts the values answered on each side. The move itself is the owner's call, and the notice is how
/// a rule author hears of it before a pipeline does. Carries the call's position for the reason
/// `incomparable_membership_notice` in `eval.rs` gives, names the call as the rule spells it, and for
/// `count` names the spelling that counts resources rather than elements.
fn list_argument_expansion_notice(
    function: &FunctionExpr<'_>,
    before: Option<&[Option<PathAwareValue>]>,
    after: &[Option<PathAwareValue>],
) -> String {
    // The notice needs a name whatever the arguments hold; a call with an argument the renderer
    // cannot write falls back to the expression's own `Display`.
    // The renderer writes a control as its escape; the `Display` fallback does not, so it is escaped
    // here, controls only, as text built from the rules file is. No parsed call reaches the fallback: a
    // filter inside a query admits only access clauses (`predicate_filter_clauses` in the parser), so
    // `function_call_as_written` renders every call the grammar produces; the escape covers a call built
    // in code, and no test can drive it through the grammar.
    let call = function_call_as_written(function).unwrap_or_else(|| {
        crate::utils::writer::escaped_controls_for_display(&function.to_string())
    });
    let location = crate::utils::writer::location_for_notice(&function.location);
    let count_of = |answers: &[Option<PathAwareValue>]| match answers.first() {
        Some(Some(PathAwareValue::Int((_, count)))) => Some(*count),
        _ => None,
    };
    let values = |n: usize| match n {
        0 => "no values".to_string(),
        1 => "1 value".to_string(),
        n => format!("{n} values"),
    };
    let answered = |answers: &[Option<PathAwareValue>]| answers.iter().flatten().count();
    match function.name {
        FunctionName::Count => {
            let (old, new) = (before.and_then(count_of), count_of(after));
            let now = match new {
                Some(new) => format!("answers {new}"),
                None => "has no answer".to_string(),
            };
            let then = match (before, old) {
                (Some(_), Some(old)) => format!("answered {old}"),
                (Some(_), None) => "had no answer".to_string(),
                (None, _) => "could not be evaluated".to_string(),
            };
            let because = match new {
                Some(_) => String::new(),
                None => " and every list among them was empty, leaving only an input the function \
                         had no answer for (a resource that lacks the property)"
                    .to_string(),
            };
            let next = match new {
                Some(new) => format!("answers {new} without it"),
                None => {
                    "gives no answer without it, and the clause fails naming the input".to_string()
                }
            };
            format!(
                "{call} {now} where it {then} before this release, because a list value \
                 the argument names is read as its elements{because}. The old count was one per list; \
                 to count the resources that carry the property, filter on it and count the filter's \
                 result (`count(<resources>[ <property> exists ])`). The notice is for this release \
                 only; the next release {next}. The call is at {location}."
            )
        }
        _ => {
            let new = answered(after);
            let then = match before {
                Some(before) if answered(before) == new => {
                    "answered as many values, not these,".to_string()
                }
                Some(before) => format!("answered {}", values(answered(before))),
                None => "could not be evaluated".to_string(),
            };
            format!(
                "{call} answers {} where it {then} before this release, because a list \
                 value among its arguments is read as its elements, where the function read the list as \
                 one value. A clause over the result that passed or was skipped on the old answer can \
                 fail or run on the new one. To read a list as one value, name the function's input as \
                 the element you mean (`<query>[0]`); to read its elements, this is now the reading. The \
                 notice is for this release only; the next release gives the new answer without it. The \
                 call is at {location}.",
                values(new)
            )
        }
    }
}

/// The unresolved result standing in for an input `name` had no answer for.
///
/// `index` is the input's position when the function answered element by element; otherwise the input
/// is the first unresolved one, since that is the only way the aggregate functions answer `None`, and
/// failing that the first input. An unresolved input is kept as it was, so a missing key reports as the
/// bare query reports it. A resolved or literal input the function could not take gets a reason, at the
/// input's own path: the function's own if it has one (`Callable::no_answer_reason`), else the general
/// one read off the function's accepted types.
///
/// `remaining_query` is empty on purpose. It is the part of a query that was not satisfied, and the
/// reporters print it as `MissingProperty = <remaining_query>`; a function's name there would say a
/// key named `to_lower(..)` was missing from a value that was found. An empty one cannot read as a
/// property name, and the console reporter prints the record as a value with no answer instead.
fn no_answer_for(
    name: &FunctionName,
    args: &[Vec<QueryResult>],
    index: Option<usize>,
) -> QueryResult {
    let inputs = args.first().map(Vec::as_slice).unwrap_or(&[]);
    let source = index
        .and_then(|index| inputs.get(index))
        .or_else(|| {
            inputs
                .iter()
                .find(|input| matches!(input, QueryResult::UnResolved(_)))
        })
        .or_else(|| inputs.first());

    match source {
        Some(QueryResult::UnResolved(unresolved)) => QueryResult::UnResolved(unresolved.clone()),
        Some(QueryResult::Literal(value)) | Some(QueryResult::Resolved(value)) => {
            QueryResult::UnResolved(UnResolved {
                traversed_to: Rc::clone(value),
                remaining_query: String::new(),
                reason: Some(
                    name.no_answer_reason(args, value)
                        .unwrap_or_else(|| general_no_answer_reason(name, value)),
                ),
                kind: UnResolvedKind::Absent,
            })
        }
        None => QueryResult::UnResolved(UnResolved {
            traversed_to: Rc::new(PathAwareValue::Null(crate::rules::path_value::Path::root())),
            remaining_query: String::new(),
            reason: Some(format!("{name} produced no value")),
            kind: UnResolvedKind::Absent,
        }),
    }
}

/// Why `name` had no answer for `value`, read off the function's own arms.
///
/// The per-element functions answer `None` without saying why, and there are two reasons they do. The
/// value is of a type the function does not take, which is the usual one. Or it is of a type the
/// function takes and the function still has nothing to say about it, which happens in three arms:
/// `substring` with a range outside the string, `url_decode` with bytes that are not UTF-8 once
/// decoded, and `parse_char` with an empty string. Everywhere else a value of an accepted type either
/// answers or is an error carrying its own message. Saying "it is String, which the function does not
/// take" for an out-of-range substring would be false, so the accepted types are listed here, copied
/// from the match arms in `functions/`, to tell the two apart. A function added there needs a row here.
/// `substring` says which of its conditions failed through `Callable::no_answer_reason`, since only its
/// call knows the bounds; the arm here is the fallback for it.
fn general_no_answer_reason(name: &FunctionName, value: &PathAwareValue) -> String {
    let accepted = match name {
        FunctionName::ToLower
        | FunctionName::ToUpper
        | FunctionName::Substring
        | FunctionName::RegexReplace
        | FunctionName::UrlDecode
        | FunctionName::JsonParse
        | FunctionName::ParseEpoch => matches!(value, PathAwareValue::String(_)),
        FunctionName::ParseInt | FunctionName::ParseFloat => matches!(
            value,
            PathAwareValue::String(_)
                | PathAwareValue::Int(_)
                | PathAwareValue::Float(_)
                | PathAwareValue::Char(_)
        ),
        FunctionName::ParseBoolean => {
            matches!(value, PathAwareValue::String(_) | PathAwareValue::Bool(_))
        }
        FunctionName::ParseString => matches!(
            value,
            PathAwareValue::String(_)
                | PathAwareValue::Int(_)
                | PathAwareValue::Float(_)
                | PathAwareValue::Bool(_)
                | PathAwareValue::Char(_)
        ),
        FunctionName::ParseChar => matches!(
            value,
            PathAwareValue::String(_) | PathAwareValue::Int(_) | PathAwareValue::Char(_)
        ),
        // These answer for the selection as a whole; a missing answer is never about one value's type.
        FunctionName::Count | FunctionName::Join | FunctionName::Now => true,
    };

    let path = value.self_path();
    if !accepted {
        return format!(
            "{name} has no answer for the value at {path}: it is {}, which the function does not take",
            value.type_info()
        );
    }
    match (name, value) {
        (FunctionName::Substring, PathAwareValue::String(_)) => format!(
            "substring has no answer for the value at {path}: the range given lies outside the string"
        ),
        (FunctionName::UrlDecode, PathAwareValue::String(_)) => format!(
            "url_decode has no answer for the value at {path}: it does not decode to valid UTF-8"
        ),
        (FunctionName::ParseChar, PathAwareValue::String(_)) => {
            format!("parse_char has no answer for the value at {path}: the string is empty")
        }
        _ => format!("{name} has no answer for the value at {path}"),
    }
}

